const API=window.CODEZONE_API_URL || window.location.origin; let token=localStorage.getItem('cz_token'); let me=null; let businessProfile={currency:'TZS',industry_profile:'retail',features:[]};
// Explicitly initialize AI state. Without aiHistory's declaration the first aiAsk() raised
// ReferenceError before entering its try/catch, so the user message never reached the API.
let aiOpen=false, aiLanguage=localStorage.getItem('cz_ai_language')||'auto', aiHistory=[], aiBusy=false;
const $=id=>document.getElementById(id); let currentPage='dashboard'; window.CZ_CURRENT_PAGE='dashboard'; let pendingCustomerId=null; const money=v=>new Intl.NumberFormat('en-TZ',{style:'currency',currency:(businessProfile.currency||'TZS').toUpperCase(),maximumFractionDigits:0}).format(Number(v||0));
async function api(path,opts={}){opts.headers={...(opts.headers||{}),'Content-Type':'application/json'}; if(token) opts.headers.Authorization=`Bearer ${token}`; const r=await fetch(API+path,opts); const t=await r.text(); let d={}; try{d=JSON.parse(t)}catch{} if(!r.ok) throw Error(d.detail||d.message||t||`HTTP ${r.status}`); return d}
function toast(s,bad=false){const e=$('toast');e.textContent=s;e.className=bad?'bad':'';setTimeout(()=>e.textContent='',3000)}
function showLogin(){$('setup').classList.add('hidden');$('login').classList.remove('hidden')};
async function loadIndustryOptions(){try{const rows=await api('/api/industry-profiles'); const el=$('industryProfile'); if(!el)return; el.innerHTML='<option value="">Choose business type</option>'+rows.map(x=>`<option value="${x.key}">${esc(x.label)} — ${esc(x.description)}</option>`).join('')}catch(e){}}
function showSetup(){$('login').classList.add('hidden');$('setup').classList.remove('hidden');loadIndustryOptions()}
$('loginForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:$('loginEmail').value,password:$('loginPassword').value})});token=d.access_token;localStorage.setItem('cz_token',token);await startApp()}catch(x){toast(x.message,true)}};
$('setupForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/setup',{method:'POST',body:JSON.stringify({business_name:$('bizName').value.trim(),industry_profile:$('industryProfile').value,name:$('ownerName').value.trim(),email:$('ownerEmail').value.trim(),phone:$('ownerPhone').value.trim()||null,address:$('ownerAddress').value.trim()||null,tin:$('ownerTin').value.trim()||null,vat_number:$('ownerVat').value.trim()||null,currency:$('ownerCurrency').value.trim().toUpperCase(),password:$('ownerPassword').value})});toast('Business setup complete. Sign in with your own account.');showLogin()}catch(x){toast(x.message,true)}};
function logout(){token=null;localStorage.removeItem('cz_token');location.reload()}
const ROLE_PAGE_ACCESS={
  owner:'*',admin:'*',
  manager:['dashboard','sales','orders','deliveries','operations','products','pricing','services','production','locations','purchases','suppliers','customers','debts','expenses','banks','shift','approvals','reports','notifications','messages','industry'],
  salesperson:['dashboard','sales','orders','deliveries','customers','debts','shift','notifications','messages'],
  storekeeper:['dashboard','products','locations','deliveries','debts','notifications','messages'],
  accountant:['dashboard','purchases','suppliers','customers','expenses','banks','debts','reports','notifications','messages'],
  cashier:['dashboard','sales','customers','debts','shift','notifications','messages']
};
function rolePageVisible(role,page){const set=ROLE_PAGE_ACCESS[String(role||'').toLowerCase()];return set==='*'||Array.isArray(set)&&set.includes(page);}
function navFeatureVisible(button){
  const page=button.dataset.page; if(!rolePageVisible(me?.role,page)) return false;
  const feature=button.dataset.feature; const group=button.dataset.navGroup; const features=new Set(businessProfile.features||[]);
  if(feature) return features.has(feature);
  if(!group || ['home','sales','admin'].includes(group)) return true;
  return features.has(group) || (group==='inventory'&&features.has('inventory')) || (group==='customers'&&features.has('customers')) || (group==='purchasing'&&features.has('purchasing')) || (group==='finance'&&features.has('finance')) || (group==='credit'&&features.has('credit')) || (group==='reports'&&features.has('reports'));
}
function applyNavigation(){
  document.querySelectorAll('#mainNav button[data-page]').forEach(b=>{const show=navFeatureVisible(b);b.classList.toggle('hidden',!show);b.setAttribute('aria-hidden',String(!show));b.setAttribute('title',b.dataset.tooltip||b.querySelector('.nav-label')?.textContent||'');b.onclick=()=>show&&loadPage(b.dataset.page)});
  document.querySelectorAll('.nav-group').forEach(group=>{const children=[...group.querySelectorAll('button[data-page]:not(.hidden)')];const visible=children.length>0;group.classList.toggle('hidden',!visible);group.querySelector('.nav-group-toggle')?.setAttribute('aria-disabled',String(!visible));});
  const industryChip=$('industryChip'); if(industryChip) industryChip.textContent=(businessProfile.industry_label||'Business').toUpperCase();
  refreshApprovalBadge();
  refreshMessageBadge();
}
function openNavGroup(name){
  document.querySelectorAll('.nav-group').forEach(g=>{const open=g.dataset.group===name;g.classList.toggle('expanded',open);g.querySelector('.nav-group-toggle')?.setAttribute('aria-expanded',String(open));g.querySelector('.nav-group-toggle')?.classList.toggle('has-active',open&&!!g.querySelector('button[data-page].active'));});
}
function syncNavForPage(p){
  document.querySelectorAll('#mainNav button[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===p));
  const parent=[...document.querySelectorAll('.nav-group')].find(g=>g.querySelector(`button[data-page="${p}"]`));
  if(parent){openNavGroup(parent.dataset.group);}else{openNavGroup('__none__');}
  document.querySelectorAll('.nav-group').forEach(g=>{g.querySelector('.nav-group-toggle')?.classList.toggle('has-active',!!g.querySelector('button[data-page].active'));});
}
async function refreshApprovalBadge(){try{const rows=await api('/api/enterprise/approvals?status=pending');const b=$('approvalsBadge');if(!b)return;const n=Array.isArray(rows)?rows.length:0;b.textContent=n>99?'99+':String(n);b.classList.toggle('hidden',n===0);}catch(_){}}
async function refreshMessageBadge(){try{const rows=await api('/api/communications/conversations');const n=(Array.isArray(rows)?rows:[]).reduce((sum,x)=>sum+Number(x.unread_count||0),0);const b=$('messagesBadge');if(!b)return;b.textContent=n>99?'99+':String(n);b.classList.toggle('hidden',n===0);}catch(_){}}
