function renderNavIcons(){document.querySelectorAll('#mainNav .nav-icon').forEach(el=>{const owner=el.closest('.nav-item,.nav-group-toggle');const label=owner?.querySelector('.nav-label')?.textContent?.trim();if(CZ_ICONS[label])el.innerHTML=CZ_ICONS[label];});}
const CZ_NAV_ITEMS=[
  ['dashboard','Home'],['sales','Sell'],['orders','Orders & Quotes'],['deliveries','Deliveries'],['operations','Returns & Adjustments'],['products','Products & Stock'],['pricing','Price Lists'],['services','Services'],['production','Production'],['locations','Branches & Warehouses'],['purchases','Purchase orders'],['suppliers','Suppliers'],['customers','Customers & CRM'],['debts','Debts & Payments'],['messages','Messages'],['expenses','Expenses'],['banks','Cash & Bank'],['shift','Shifts'],['approvals','Approvals'],['reports','Reports & Analytics'],['notifications','Notifications'],['employees','Employees'],['users','Users & Roles'],['email','Company Email'],['settings','Settings'],['enterprise','Enterprise'],['industry','Industry & Platform'],['cloud','Cloud & Sync']
].map(([page,label])=>({page,label}));
let commandIndex=0,commandItems=[];
function openCommandPalette(prefill=''){const o=$('commandPalette');if(!o)return;o.classList.remove('hidden');const input=$('commandInput');input.value=prefill;renderCommandResults(prefill);setTimeout(()=>input.focus(),20);}
function closeCommandPalette(){const o=$('commandPalette');if(o)o.classList.add('hidden');}
async function buildCommandItems(){return CZ_NAV_ITEMS.filter(x=>rolePageVisible(me?.role,x.page)).map(x=>({kind:'page',title:x.label,subtitle:'Open module',page:x.page,icon:'→'}));}
async function renderCommandResults(query=''){const q=String(query||'').trim().toLowerCase();if(!commandItems.length)commandItems=await buildCommandItems();let items=commandItems.filter(x=>!q||x.title.toLowerCase().includes(q)||x.subtitle.toLowerCase().includes(q));if(q.length>=2){try{const [products,customers]=await Promise.all([api('/api/products'),api('/api/customers')]);for(const p of (products||[])){const hay=`${p.name||''} ${p.sku||''}`.toLowerCase();if(hay.includes(q))items.push({kind:'product',title:p.name||p.sku||'Product',subtitle:`Product · ${p.sku||'—'}`,page:'products',icon:'◫'});}for(const x of (customers||[])){const hay=`${x.name||''} ${x.phone||''} ${x.email||''}`.toLowerCase();if(hay.includes(q))items.push({kind:'customer',title:x.name||'Customer',subtitle:'Customer · open CRM',page:'customers',icon:'◎'});}}catch(_){} }
const box=$('commandResults');if(!box)return;if(!items.length){box.innerHTML='<div class="command-empty">No matching pages or records.</div>';commandIndex=0;return;}commandIndex=Math.min(commandIndex,items.length-1);box.innerHTML=items.slice(0,12).map((x,i)=>`<button type="button" class="command-row ${i===commandIndex?'selected':''}" data-cmd-index="${i}"><span class="command-icon">${x.icon}</span><span><strong>${esc(x.title)}</strong><small>${esc(x.subtitle)}</small></span><kbd>${x.kind==='page'?'Open':'View'}</kbd></button>`).join('');box.querySelectorAll('[data-cmd-index]').forEach(btn=>btn.onclick=()=>{const x=items[Number(btn.dataset.cmdIndex)];closeCommandPalette();loadPage(x.page);});}
function setupGlobalTools(){if(window.__czGlobalToolsReady)return;window.__czGlobalToolsReady=true;const input=$('globalSearch'),cmd=$('commandInput'),quick=$('quickCreateMenu');$('sidebarToggle')?.focus; document.querySelector('.global-search-wrap')?.addEventListener('click',()=>{if(window.innerWidth<=1024)openCommandPalette();}); $('quickCreateBtn')?.addEventListener('click',()=>{quick?.classList.toggle('hidden');});$('closeQuickCreate')?.addEventListener('click',()=>quick?.classList.add('hidden'));quick?.querySelectorAll('[data-quick-page]').forEach(b=>b.addEventListener('click',()=>{quick.classList.add('hidden');loadPage(b.dataset.quickPage);}));input?.addEventListener('focus',()=>openCommandPalette(input.value));input?.addEventListener('input',e=>{if(!$('commandPalette')?.classList.contains('hidden'))renderCommandResults(e.target.value);});input?.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();input.blur();closeCommandPalette();}if(e.key==='Enter'){e.preventDefault();openCommandPalette(input.value);}});cmd?.addEventListener('input',e=>{commandIndex=0;renderCommandResults(e.target.value);});cmd?.addEventListener('keydown',e=>{const buttons=[...($('commandResults')?.querySelectorAll('.command-row')||[])];if(e.key==='ArrowDown'){e.preventDefault();commandIndex=Math.min(commandIndex+1,buttons.length-1);renderCommandResults(cmd.value);}if(e.key==='ArrowUp'){e.preventDefault();commandIndex=Math.max(commandIndex-1,0);renderCommandResults(cmd.value);}if(e.key==='Enter'){e.preventDefault();buttons[commandIndex]?.click();}if(e.key==='Escape'){e.preventDefault();closeCommandPalette();}});$('closeCommandPalette')?.addEventListener('click',closeCommandPalette);$('commandPalette')?.addEventListener('click',e=>{if(e.target.id==='commandPalette')closeCommandPalette();});window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommandPalette();}});}
function aiAnalyzeCurrentPage(){aiSetOpen(true);const page=window.CZ_CURRENT_PAGE||'dashboard';const prompt=aiLanguage==='sw'?`Chambua ukurasa wa ${page} kwa kutumia data ya CODEZONE. Nipe mambo 3 muhimu ninayopaswa kujua, sababu zake, hatari na hatua 3 za kuchukua.`:`Analyze the ${page} page using verified CODEZONE business data. Give me the 3 most important findings, why they matter, the risks, and 3 recommended actions.`;aiAsk(prompt);}
function initSidebar(){
  if(window.__czSidebarReady)return; window.__czSidebarReady=true;
  const sidebar=$('sidebar'),overlay=$('sidebarOverlay'),toggle=$('sidebarToggle');
  const saved=localStorage.getItem('cz_sidebar_collapsed')==='1'; if(saved && window.innerWidth>1024) sidebar.classList.add('is-collapsed');
  const closeDrawer=()=>{sidebar.classList.remove('drawer-open');overlay.classList.remove('visible');overlay.setAttribute('aria-hidden','true')};
  toggle.onclick=()=>{if(window.innerWidth<=1024){const open=sidebar.classList.toggle('drawer-open');overlay.classList.toggle('visible',open);overlay.setAttribute('aria-hidden',String(!open));}else{const collapsed=sidebar.classList.toggle('is-collapsed');localStorage.setItem('cz_sidebar_collapsed',collapsed?'1':'0')}};
  overlay.onclick=closeDrawer;
  document.querySelectorAll('.nav-group-toggle').forEach(btn=>btn.onclick=()=>{const group=btn.closest('.nav-group');const name=group.dataset.group;if(window.innerWidth<=1024)closeDrawer(); if(sidebar.classList.contains('is-collapsed')&&window.innerWidth>1024){group.classList.toggle('flyout-open');return;} const open=group.classList.contains('expanded');openNavGroup(open?'__none__':name);});
  document.querySelectorAll('#mainNav button[data-page]').forEach(b=>b.addEventListener('click',()=>{if(window.innerWidth<=1024)closeDrawer();}));
  window.addEventListener('resize',()=>{if(window.innerWidth>1024){closeDrawer();}else{sidebar.classList.remove('is-collapsed');}});
}
async function refreshOperationalHeader(){try{const active=await api('/api/platform/shift/current'); const btn=$('shiftHeader'), text=$('shiftHeaderText'); if(!btn||!text)return; const open=!!active&&active.status==='open'; text.textContent=open?'Shift open':'Shift closed'; btn.title=open?`Open shift · ${active.branch_name||'Branch'} · ${active.sales_count||0} sales`:'Open your shift before selling'; btn.onclick=()=>loadPage('shift'); btn.classList.toggle('status-good',open); btn.classList.toggle('status-closed',!open); btn.querySelector('.shift-dot')?.classList.toggle('is-open',open);}catch(_){const btn=$('shiftHeader'),text=$('shiftHeaderText');if(btn&&text){text.textContent='Shift status unavailable';btn.onclick=()=>loadPage('shift');btn.classList.remove('status-good','status-closed');btn.querySelector('.shift-dot')?.classList.remove('is-open');}}}

async function initBranchSelector(){const sel=$('branchSelector');if(!sel)return;try{const rows=await api('/api/platform/branches'); if(!Array.isArray(rows)||!rows.length){sel.innerHTML='<option value="">Branch</option>';return;} const saved=localStorage.getItem('cz_branch_id'); const preferred=rows.find(x=>String(x.id)===saved)||rows.find(x=>x.is_default)||rows[0]; sel.innerHTML=rows.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join(''); sel.value=String(preferred.id); sel.onchange=()=>localStorage.setItem('cz_branch_id',sel.value);}catch(_){sel.innerHTML='<option value="">Branch</option>';sel.disabled=true;}}

function initUserMenu(){if(window.__czUserMenuReady)return;window.__czUserMenuReady=true;const btn=$('userMenuBtn'),menu=$('userMenu'); if(!btn||!menu)return; const close=()=>{menu.classList.add('hidden');btn.setAttribute('aria-expanded','false');}; btn.onclick=(e)=>{e.stopPropagation();const open=menu.classList.toggle('hidden');btn.setAttribute('aria-expanded',String(!open));}; menu.querySelectorAll('[data-user-action]').forEach(b=>b.addEventListener('click',()=>{const a=b.dataset.userAction;close();if(a==='logout')logout();if(a==='settings')loadPage('settings');}));document.addEventListener('click',e=>{if(!menu.contains(e.target)&&e.target!==btn)close();});}

async function startApp(){try{initSidebar();renderNavIcons();initAI();setupGlobalTools();initUserMenu();me=await api('/api/auth/me'); businessProfile=await api('/api/business-profile');$('login').classList.add('hidden');$('setup').classList.add('hidden');$('app').classList.remove('hidden');const initials=(me.name||'CZ').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();$('userName').textContent=me.name;$('userRole').textContent=me.role;$('userAvatar').textContent=initials;$('topUserAvatar').textContent=initials;$('topUserName').textContent=me.name;$('menuUserAvatar').textContent=initials;$('menuUserName').textContent=me.name;$('menuUserRole').textContent=me.role;applyNavigation();await Promise.all([refreshOperationalHeader(),initBranchSelector()]);await loadPage('dashboard');window.clearInterval(window.__czHeaderTimer);window.__czHeaderTimer=window.setInterval(refreshOperationalHeader,30000);window.clearInterval(window.__czMessageBadgeTimer);window.__czMessageBadgeTimer=window.setInterval(refreshMessageBadge,15000)}catch(e){token=null;localStorage.removeItem('cz_token');showLogin();toast('Login succeeded, but the application could not finish loading: '+(e.message||'Unknown error'),true)}}
(async()=>{try{const s=await api('/api/setup/status');if(s.setup_required)showSetup();else if(token)startApp();else showLogin()}catch(e){toast('Application service is not running.',true)}})();

function aiSetLanguage(lang){aiLanguage=lang||'auto';localStorage.setItem('cz_ai_language',aiLanguage);const el=$('aiLanguage');if(el)el.value=aiLanguage;}
function aiAppend(role,text,source,meta){const box=$('aiChat');if(!box)return;const el=document.createElement('div');el.className=`ai-msg ${role}`;el.textContent=text;if(meta?.evidence?.length){const ev=document.createElement('div');ev.className='ai-evidence';ev.textContent='Evidence: '+meta.evidence.join(' · ');el.appendChild(ev)}if(meta?.actions?.length){const ul=document.createElement('ul');ul.className='ai-action-list';meta.actions.slice(0,5).forEach(a=>{const li=document.createElement('li');li.textContent=a;ul.appendChild(li)});el.appendChild(ul)}if(source){const s=document.createElement('div');s.className='ai-source';s.textContent=source;el.appendChild(s)}box.appendChild(el);box.scrollTop=box.scrollHeight}
function aiSetOpen(open){aiOpen=!!open;const p=$('aiPanel'),f=$('aiFab');if(!p)return;p.classList.toggle('open',aiOpen);p.setAttribute('aria-hidden',String(!aiOpen));if(f)f.classList.toggle('hidden',aiOpen);if(aiOpen){$('aiInput')?.focus();aiLoadInsights();aiLoadStatus();}}
function aiClear(){aiHistory=[];const box=$('aiChat');if(box)box.innerHTML='<div class="ai-welcome"><strong>New CODEZONE AI conversation.</strong><span>Ask for a decision, diagnosis, forecast, plan or explanation.</span></div>';aiLoadInsights();}
async function aiLoadStatus(){try{const s=await api('/api/ai/status');const el=$('aiStatus');if(!el)return;if(s.remote_configured){el.textContent=s.remote_available===false?`AI provider issue · fallback active (${s.last_error||'connection'})`:s.remote_available===true?`AI online · ${s.model}`:`Provider configured · test connection (${s.model})`;}else{el.textContent='Local advisor · limited mode';}el.title=s.note||'';const cfg=$('aiConfigure');if(cfg)cfg.classList.toggle('hidden',!['owner','admin'].includes(String(me?.role||'').toLowerCase()));const mode=$('aiMode');if(mode)mode.textContent=s.remote_configured?(s.remote_available===false?'Fallback':s.remote_available===true?'Online':'Test provider'):'Limited';}catch(e){const el=$('aiStatus');if(el)el.textContent='AI status unavailable';}}
function aiRenderInsights(items){const box=$('aiInsights');if(!box)return;box.innerHTML=(items||[]).map(x=>`<div class="ai-insight ${esc(x.severity||'info')}"><div class="ai-insight-title">${esc(x.title||'Insight')}</div><div class="ai-insight-message">${esc(x.message||'')}</div>${x.action_label?`<div class="ai-insight-action">${esc(x.action_label)}</div>`:''}</div>`).join('');}
async function aiLoadInsights(){try{const d=await api('/api/ai/insights');aiRenderInsights(d.items||[]);}catch(_){} }
async function aiAsk(message){const q=String(message||'').trim();if(!q||aiBusy)return;const input=$('aiInput'),chat=$('aiChat'),send=$('aiForm')?.querySelector('button[type="submit"]');aiBusy=true;if(send)send.disabled=true;let loading=null;try{aiAppend('user',q);aiHistory.push({role:'user',content:q});if(input)input.value='';loading=document.createElement('div');loading.className='ai-msg assistant';loading.textContent=aiLanguage==='sw'?'Ninafanya uchambuzi…':'Thinking through the business data…';chat?.appendChild(loading);if(chat)chat.scrollTop=chat.scrollHeight;const r=await api('/api/ai/chat',{method:'POST',body:JSON.stringify({message:q,page:window.CZ_CURRENT_PAGE||'dashboard',language:aiLanguage,history:aiHistory.slice(-10)})});if(r.mode==='local_fallback'){const status=$('aiStatus');if(status)status.textContent='AI provider issue · fallback active';}else if(r.mode==='remote'){const status=$('aiStatus');if(status)status.textContent='AI online';}loading?.remove();loading=null;const answer=r.answer||((aiLanguage==='sw')?'Samahani, sijapata jibu. Jaribu kuuliza kwa namna nyingine.':'Sorry, I could not produce an answer. Please rephrase the question.');const displayedAnswer=answer+(r.provider_notice?'\n\nℹ '+r.provider_notice:'');aiAppend('assistant',displayedAnswer,r.source||'CODEZONE AI',r);aiHistory.push({role:'assistant',content:answer});const sug=$('aiSuggestions');if(sug&&Array.isArray(r.suggestions)){sug.innerHTML=r.suggestions.slice(0,6).map(x=>`<button type="button">${esc(x)}</button>`).join('');sug.querySelectorAll('button').forEach(b=>b.onclick=()=>aiAsk(b.textContent));}}catch(e){loading?.remove();aiAppend('assistant',(aiLanguage==='sw'?'AI haikuweza kujibu: ':'AI could not respond: ')+(e.message||'Huduma haipatikani kwa sasa.'));}finally{aiBusy=false;if(send)send.disabled=false;if(input)input.focus();}}
function initAI(){if(window.__czAIReady)return;window.__czAIReady=true;const fab=$('aiFab'),close=$('aiClose'),clear=$('aiClear'),form=$('aiForm');$('aiAnalyzePage')?.addEventListener('click',aiAnalyzeCurrentPage);aiSetLanguage(aiLanguage);fab?.addEventListener('click',()=>aiSetOpen(true));close?.addEventListener('click',()=>aiSetOpen(false));clear?.addEventListener('click',aiClear);form?.addEventListener('submit',e=>{e.preventDefault();aiAsk($('aiInput').value)});$('aiConfigure')?.addEventListener('click',()=>loadPage('settings'));$('aiLanguage')?.addEventListener('change',e=>aiSetLanguage(e.target.value));$('aiSuggestions')?.querySelectorAll('button').forEach(b=>b.onclick=()=>aiAsk(b.textContent));window.addEventListener('keydown',e=>{if(e.key==='Escape'&&aiOpen)aiSetOpen(false);if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='j'){e.preventDefault();aiSetOpen(!aiOpen);}});}
async function loadPage(p){
  currentPage=p; window.CZ_CURRENT_PAGE=p;
  syncNavForPage(p);
  const labels={dashboard:['Dashboard','Business control center'],sales:['Sell','Point of sale, invoices & payments'],orders:['Orders & Quotes','Quotations and sales orders'],deliveries:['Deliveries','Pick, dispatch and track customer deliveries'],services:['Services','Service jobs, assignments and completion'],production:['Production','Recipes, production orders and stock transformation'],enterprise:['Enterprise','Taxes, customer groups, loyalty and warehouse controls'],approvals:['Approvals','Review controlled business actions'],notifications:['Notifications','Alerts, approvals and operational messages'],messages:['Messages','Private messages, group conversations and assigned tasks'],purchases:['Purchasing','Suppliers, receiving & bills'],products:['Inventory','Products, services & stock'],customers:['Customers & CRM','Accounts, credit & customer history'],suppliers:['Suppliers','Supplier accounts & purchasing'],expenses:['Expenses','Business operating costs'],banks:['Cash & Bank','Cash and bank accounts'],debts:['Credit & Payments','Receivables, payables & settlements'],reports:['Reports & Analytics','Business intelligence & reporting'],locations:['Branches & Warehouses','Multi-location stock and operations'],pricing:['Price Lists','Retail, wholesale and special pricing'],shift:['Shifts','Cashier opening and closing'],industry:['Industry & Platform','Industry profiles and platform capabilities'],cloud:['Cloud & Sync','Devices, online orders and synchronization'],containers:['Industry Features','Optional industry-specific controls'],operations:['Returns & Adjustments','Returns, stock and settlements'],settings:['Settings','Business configuration & setup'],employees:['Employees','HR employee records, independent of login access'],users:['Users & Roles','Manage CODEZONE login accounts and permissions'],email:['Company Email','Configure the company mail domain and mailbox provider']};
  const pageTitle=$('pageTitle'); if(pageTitle) pageTitle.textContent=labels[p]?.[0]||p[0].toUpperCase()+p.slice(1); const pageSub=$('pageSub'); if(pageSub) pageSub.textContent=labels[p]?.[1]||''; const pageCrumb=$('pageCrumb'); if(pageCrumb) pageCrumb.textContent=(p==='dashboard'?'Home':`Home / ${labels[p]?.[0]||p}`);
  const c=$('content'); c.innerHTML='<div class="panel"><div class="muted">Loading…</div></div>';
  try{
    if(p==='dashboard')return await dashboard(c); if(p==='deliveries')return await deliveriesPage(c); if(p==='services')return await servicesPage(c); if(p==='production')return await productionPage(c); if(p==='enterprise')return await enterprisePage(c); if(p==='approvals')return await approvalsPage(c); if(p==='notifications')return await notificationsPage(c); if(p==='messages')return await messagesPage(c); if(p==='employees')return await employeesPage(c); if(p==='email')return await companyEmailPage(c); if(p==='products')return await products(c); if(p==='customers')return await customers(c); if(p==='suppliers')return await suppliers(c); if(p==='banks')return await banks(c); if(p==='sales')return await sales(c); if(p==='orders')return await ordersPage(c); if(p==='purchases')return await purchases(c); if(p==='expenses')return await expenses(c); if(p==='debts')return await debts(c); if(p==='reports')return await reports(c); if(p==='locations')return await locationsPage(c); if(p==='pricing')return await pricingPage(c); if(p==='shift')return await shiftPage(c); if(p==='industry')return await industryPage(c); if(p==='cloud')return await cloudPage(c); if(p==='users')return await usersPage(c); if(p==='containers')return await containersPage(c); if(p==='operations')return await operationsPage(c); if(p==='settings')return await settingsPage(c);
  }catch(e){
    c.innerHTML=`<div class="panel dashboard-error"><h3>Unable to open ${esc(labels[p]?.[0]||p)}</h3><p class="muted">${esc(e.message||'Unexpected application error.')}</p><button onclick="loadPage('${p}')">Retry</button></div>`;
  }
}
async function dashboard(c){
  const d=await api('/api/dashboard');
  const today=new Date();
  const hour=today.getHours();
  const greeting=hour<12?'Good morning':hour<18?'Good afternoon':'Good evening';
  const ownerName=me?.name||businessProfile.owner_name||'there';
  const dateLabel=today.toLocaleDateString('en-TZ',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
  const week=d.week_sales||[];
  const maxWeek=Math.max(...week.map(x=>Number(x.total||0)),1);
  const chart=week.map(x=>`<div class="sales-bar-item"><div class="sales-bar-value">${money(x.total)}</div><div class="sales-bar-track"><div class="sales-bar-fill" style="height:${Math.max(4,(Number(x.total||0)/maxWeek)*100)}%"></div></div><div class="sales-bar-label">${esc(x.label)}</div></div>`).join('');
  const recent=(d.recent_sales||[]).map(x=>`<tr><td><strong>${esc(x.invoice_no)}</strong><small>${esc(x.customer_name)}</small></td><td>${money(x.total)}</td><td><span class="sale-status sale-status-${String(x.payment_status||'').toLowerCase()}">${esc(x.payment_status)}</span></td><td>${esc(x.sale_date)}</td></tr>`).join('');
  const attention=(d.attention||[]).map(x=>`<button class="dashboard-attention-row ${x.type}" type="button" onclick="loadPage('${x.page}')"><span class="attention-icon">${x.type==='low_stock'?'!':x.type==='expiring'?'⌛':x.type==='overdue'?'◐':'✓'}</span><span><strong>${esc(x.title)}</strong><small>${esc(x.detail)}</small></span><span class="attention-arrow">→</span></button>`).join('');
  const allGood=!attention;
  c.innerHTML=`
    <div class="dashboard-home">
      <section class="dashboard-greeting"><div><h1>${greeting}, ${esc(ownerName)}</h1><p>${esc(dateLabel)}</p></div><span class="dashboard-business-tag">${esc(businessProfile.industry_label||'Business')}</span></section>

      <section class="dashboard-kpis">
        <article class="home-kpi sales-kpi"><div class="kpi-label">Sales today</div><strong>${money(d.today_sales)}</strong><button type="button" onclick="loadPage('sales')">View sales →</button></article>
        <article class="home-kpi"><div class="kpi-label">Paid today</div><strong>${money(d.today_paid)}</strong><button type="button" onclick="loadPage('debts')">View payments →</button></article>
        <article class="home-kpi"><div class="kpi-label">Customer receivables</div><strong>${money(d.customer_debt)}</strong><button type="button" onclick="loadPage('customers')">Review customers →</button></article>
        <article class="home-kpi"><div class="kpi-label">Stock value</div><strong>${d.stock_value==null?'—':money(d.stock_value)}</strong><button type="button" onclick="loadPage('products')">Open stock →</button></article>
      </section>

      <section class="dashboard-main-grid">
        <div class="dashboard-left-stack">
          <article class="home-card sales-week-card">
            <div class="home-card-head"><div><h2>Sales this week</h2><p>Net posted sales by day.</p></div><button class="quiet-action" type="button" onclick="loadPage('reports')">View report →</button></div>
            <div class="sales-chart" aria-label="Sales this week chart">${chart||'<div class="empty">No sales recorded this week.</div>'}</div>
          </article>
          <article class="home-card recent-sales-card">
            <div class="home-card-head"><div><h2>Recent sales</h2><p>Last 5 posted transactions.</p></div><button class="quiet-action" type="button" onclick="loadPage('sales')">View all →</button></div>
            <div class="recent-sales-table-wrap">${recent?`<table class="recent-sales-table"><thead><tr><th>Invoice / Customer</th><th>Total</th><th>Status</th><th>Date</th></tr></thead><tbody>${recent}</tbody></table>`:'<div class="empty">No recent sales yet.</div>'}</div>
          </article>
        </div>
        <aside class="home-card attention-card">
          <div class="home-card-head"><div><h2>Needs attention</h2><p>Only active issues are shown.</p></div></div>
          ${allGood?`<div class="attention-all-good"><span class="all-good-mark">✓</span><div><strong>All good</strong><small>No immediate issues need your attention.</small></div></div>`:`<div class="dashboard-attention-list">${attention}</div>`}
          ${allGood?'':`<div class="attention-summary">${d.low_stock_count?`<span>Low stock ${d.low_stock_count}</span>`:''}${d.expiring_batch_count?`<span>Expiring ${d.expiring_batch_count}</span>`:''}${d.overdue_receivables?`<span>Overdue ${money(d.overdue_receivables)}</span>`:''}${d.pending_approval_count?`<span>Approvals ${d.pending_approval_count}</span>`:''}</div>`}
        </aside>
      </section>
    </div>`;
}

async function products(c){
  const rows=await api('/api/products');
  c.innerHTML=`<div class="grid"><div class="panel"><h3>Add item</h3><form id="pf"><div class="formgrid"><select id="itemType"><option value="product">Product</option><option value="service">Service</option></select><input id="sku" placeholder="SKU / Code" required><input id="pn" placeholder="Product or service name" required><input id="brand" placeholder="Brand (optional)"><input id="barcode" placeholder="Barcode (optional)"><input id="bp" type="number" step="0.01" placeholder="Cost price"><input id="sp" type="number" step="0.01" placeholder="Selling price"><input id="stock" type="number" step="0.001" placeholder="Opening stock"><input id="min" type="number" step="0.001" placeholder="Reorder level"></div><label class="check-row"><input id="trackInventory" type="checkbox" checked> Track inventory for this item</label><button type="submit">Add item</button></form></div><div class="panel"><div class="section-head"><div><h3>Products & Services</h3><p class="muted">One item engine for physical goods and services.</p></div></div>${table(['Type','SKU','Name','Barcode','Sell','Stock','Action'],rows.map(x=>[x.item_type==='service'?'Service':'Product',x.sku,x.name,x.barcode||'—',money(x.selling_price),x.track_inventory?x.stock:'—',`<div style="display:flex;gap:6px"><button onclick="editProduct(${x.id})">Edit</button><button class="danger" onclick="deleteProduct(${x.id},'${String(x.name).replace(/'/g,"\\'")}')">Delete</button></div>`]))}</div></div>`;
  window._products=rows;
  $('itemType').onchange=()=>{const service=$('itemType').value==='service';$('trackInventory').checked=!service;$('trackInventory').disabled=service;$('stock').disabled=service;$('min').disabled=service};
  $('pf').onsubmit=async e=>{e.preventDefault();try{await api('/api/products',{method:'POST',body:JSON.stringify({sku:$('sku').value,name:$('pn').value,item_type:$('itemType').value,barcode:$('barcode').value.trim()||null,brand:$('brand').value.trim()||null,track_inventory:$('trackInventory').checked,buying_price:Number($('bp').value||0),selling_price:Number($('sp').value||0),minimum_stock:Number($('min').value||0),reorder_level:Number($('min').value||0),current_stock:Number($('stock').value||0)})});toast('Item added');loadPage('products')}catch(x){toast(x.message,true)}};
}

async function editProduct(id){
  const p=window._products.find(x=>x.id===id); if(!p)return;
  const itemType=prompt('Type (product/service):',p.item_type||'product'); if(itemType===null)return;
  if(!['product','service'].includes(itemType.trim().toLowerCase()))return toast('Type must be product or service.',true);
  const sku=prompt('SKU / Code:',p.sku); if(sku===null)return;
  const name=prompt('Name:',p.name); if(name===null)return;
  const barcode=prompt('Barcode (optional):',p.barcode||''); if(barcode===null)return;
  const brand=prompt('Brand (optional):',p.brand||''); if(brand===null)return;
  const buying=prompt('Cost price:',p.buying_price); if(buying===null)return;
  const selling=prompt('Selling price:',p.selling_price); if(selling===null)return;
  const minimum=prompt('Reorder level:',p.reorder_level||p.minimum_stock); if(minimum===null)return;
  try{await api(`/api/products/${id}`,{method:'PUT',body:JSON.stringify({sku:sku.trim(),name:name.trim(),item_type:itemType.trim().toLowerCase(),barcode:barcode.trim()||null,brand:brand.trim()||null,track_inventory:itemType.trim().toLowerCase()==='product'&&!!p.track_inventory,buying_price:Number(buying||0),selling_price:Number(selling||0),minimum_stock:Number(minimum||0),reorder_level:Number(minimum||0)})});toast('Item updated');loadPage('products')}catch(x){toast(x.message,true)}
}

async function deleteProduct(id,name){
  if(!confirm(`Delete product "${name}"?`))return;

  try{
    await api(`/api/products/${id}`,{method:'DELETE'});
    toast('Product deleted');
    loadPage('products');

  }catch(x){
    toast(x.message,true);
  }
}
function startSaleForCustomer(id){pendingCustomerId=Number(id)||null;loadPage('sales');}
