  c.innerHTML=`<div class="grid customer-grid"><div><div class="panel"><h3>Add customer</h3><form id="cf"><input id="cn" placeholder="Name" required><input id="cp" placeholder="Phone"><input id="ca" placeholder="Address"><div class="formgrid"><input id="cl" type="number" step="0.01" min="0" placeholder="Credit limit"><input id="ct" type="number" min="0" placeholder="Payment terms (days)"></div><select id="cg"><option value="">No customer group</option>${groups.map(g=>`<option value="${g.id}">${esc(g.name)} — ${g.discount_percent}%</option>`).join('')}</select><button>Add customer</button></form></div><div class="panel" style="margin-top:15px"><h3>Customers</h3>${table(['Name','Phone','Group','Credit limit','Terms','Action'],rows.map(x=>[esc(x.name),esc(x.phone||'—'),esc(groups.find(g=>g.id===x.group_id)?.name||'—'),money(x.credit_limit),x.payment_terms_days+' days',`<button onclick="openCustomer360(${x.id})">View 360</button>`]))}</div></div><div id="customer360" class="panel"><div class="empty">Select a customer to view Customer 360.</div></div></div>`;
