async function sales(c){
  const [ps,cs,banks,units,containers,warehouses,priceLists,taxRates,branches,shift]=await Promise.all([
    api('/api/products'),api('/api/customers'),api('/api/banks'),api('/api/units'),api('/api/empty-containers'),
    api('/api/platform/warehouses'),api('/api/platform/price-lists'),api('/api/enterprise/tax-rates'),api('/api/platform/branches'),api('/api/platform/shift/current')
  ]);
  if(!shift){c.innerHTML=`<div class="shift-required panel"><div class="shift-required-icon">◷</div><div><span class="eyebrow">REGISTER CONTROL</span><h3>Open your shift before selling</h3><p class="muted">Start the shift when you arrive at the shop. CODEZONE uses the shift to record sales, cash movements and your end-of-day reconciliation.</p><div class="hero-actions"><button onclick="loadPage('shift')">Open shift</button><button class="secondary" onclick="loadPage('dashboard')">Back to dashboard</button></div></div></div>`;return;}
  const today=new Date().toLocaleDateString('en-CA',{timeZone:'Africa/Dar_es_Salaam'});
  const preview=`INV-${today.replaceAll('-','')}-AUTO`;
  const customerOptions=cs.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');
  const bankOptions=banks.map(x=>`<option value="${x.id}">${esc(x.bank_name)} — ${esc(x.account_number)}</option>`).join('');
  const unitOptions=`<option value="">Base unit</option>`+units.map(x=>`<option value="${x.id}">${esc(x.name)} (${esc(x.symbol)})</option>`).join('');
  const containerOptions=`<option value="">No container</option>`+containers.map(x=>`<option value="${x.id}">${esc(x.name)} — stock ${esc(x.current_stock)}</option>`).join('');
  const warehouseOptions=`<option value="">Global stock</option>`+warehouses.map(x=>`<option value="${x.id}">${esc(x.name)}${x.branch_id?' — branch':''}</option>`).join('');
  const priceListOptions=`<option value="">Standard product/customer pricing</option>`+priceLists.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');
  const taxOptions=`<option value="">No tax</option>`+taxRates.map(x=>`<option value="${x.id}" data-rate="${x.rate}" data-inclusive="${x.inclusive?'1':'0'}">${esc(x.name)} — ${x.rate}%${x.inclusive?' inclusive':''}</option>`).join('');
  const branchOptions=`<option value="">No branch</option>`+branches.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');
  c.innerHTML=`<div class="sales-page"><div class="sales-toolbar panel"><div><div class="eyebrow">POINT OF SALE</div><h3>New Sale</h3><p class="muted">Sell products or services with warehouse, price-list, tax and split-payment controls.</p></div><div class="sales-toolbar-actions"><span class="invoice-badge">${esc(preview)}</span><button type="button" class="secondary" id="clearSale">Clear</button></div></div><div class="sales-layout"><section class="panel sale-builder"><div class="section-head"><div><h3>Items</h3><span class="muted">Prices can be resolved automatically from the selected customer/price list.</span></div><button type="button" id="addSaleItem">+ Add item</button></div><div id="saleItems" class="sale-items"></div><div id="saleEmpty" class="empty">Add at least one product or service to continue.</div></section><aside class="panel sale-summary"><h3>Sale summary</h3><div class="invoice-readonly"><small>Invoice number</small><strong>${esc(preview)}</strong></div><div class="formgrid"><label>Branch<select id="branch">${branchOptions}</select></label><label>Warehouse<select id="warehouse">${warehouseOptions}</select></label><label>Price list<select id="priceList">${priceListOptions}</select></label><label>Tax<select id="taxRate">${taxOptions}</select></label></div><label>Customer<select id="customer"><option value="">Walk-in customer</option>${customerOptions}</select></label><label>Payment method<select id="method"><option value="cash">Cash</option><option value="bank">Bank</option><option value="mobile_money">Mobile Money</option><option value="card">Card</option><option value="cheque">Cheque</option><option value="split">Split / Mixed</option></select></label><label id="bankWrap" class="hidden">Bank account<select id="bank"><option value="">Select bank</option>${bankOptions}</select></label><div id="splitWrap" class="panel hidden" style="margin:8px 0"><h4>Split payment</h4><div class="formgrid"><select class="splitMethod"><option value="cash">Cash</option><option value="mobile_money">Mobile Money</option><option value="card">Card</option><option value="bank">Bank</option><option value="cheque">Cheque</option></select><input class="splitAmount" type="number" min="0" step="0.01" value="0"><select class="splitBank hidden"><option value="">Bank account</option>${bankOptions}</select><input class="splitRef" placeholder="Reference"></div><div class="formgrid"><select class="splitMethod"><option value="cash">Cash</option><option value="mobile_money">Mobile Money</option><option value="card">Card</option><option value="bank">Bank</option><option value="cheque">Cheque</option></select><input class="splitAmount" type="number" min="0" step="0.01" value="0"><select class="splitBank hidden"><option value="">Bank account</option>${bankOptions}</select><input class="splitRef" placeholder="Reference"></div><div class="muted">Split paid: <strong id="splitPaid">${money(0)}</strong></div></div><div class="summary-box"><div><span>Subtotal</span><strong id="saleSubtotal">${money(0)}</strong></div><div><label>Discount<input id="disc" type="number" min="0" step="0.01" value="0"></label></div><div><span>Tax</span><strong id="saleTax">${money(0)}</strong></div><div class="grand"><span>Total</span><strong id="saleGrandTotal">${money(0)}</strong></div><div><label>Amount paid<input id="paid" type="number" min="0" step="0.01" value="0"></label></div><div><span>Balance</span><strong id="saleBalance">${money(0)}</strong></div></div><div class="panel" style="margin-top:10px"><h4>Empty containers</h4><label>Type<select id="containerType">${containerOptions}</select></label><div class="formgrid"><label>Issued<input id="containersIssued" type="number" min="0" step="0.001" value="0"></label><label>Returned<input id="containersReturned" type="number" min="0" step="0.001" value="0"></label></div><div id="containerDeposit" class="muted">Deposit: ${money(0)}</div></div><label class="override-row hidden" id="belowCostWrap"><input id="belowCost" type="checkbox"> Approve below-cost sale (manager/owner only)</label><label>Reference<input id="ref" maxlength="120" placeholder="Receipt/reference (optional)"></label><button type="submit" form="saleF" id="postSale" class="primary-action">Complete Sale</button><div id="saleMessage" class="form-message" aria-live="polite"></div></aside></div><section class="panel sales-history-panel"><div class="section-head"><div><h3>Sales History</h3><span class="muted">Search and review posted transactions.</span></div><button type="button" class="secondary" onclick="salesAll()">All history</button></div><div class="toolbar sales-filters"><input id="salesFrom" type="date" value="${today}"><input id="salesTo" type="date" value="${today}"><select id="salesStatus"><option value="">All statuses</option><option>PAID</option><option>PARTIAL</option><option>CREDIT</option></select><select id="salesCustomer"><option value="">All customers</option>${customerOptions}</select><input id="salesSearch" placeholder="Invoice or customer"><button type="button" onclick="salesHistory()">Search</button></div><div id="salesHistoryTable"><div class="empty">Loading sales...</div></div></section></div><form id="saleF" class="hidden"></form>`;
  let rows=[];
  const priceFor=async(el)=>{
    const pid=Number(el.querySelector('.siProduct').value), uid=el.querySelector('.siUnit').value?Number(el.querySelector('.siUnit').value):null;
    if(!pid)return;
    try{
      const q=new URLSearchParams({product_id:String(pid)}); if($('customer').value)q.set('customer_id',$('customer').value); if($('priceList').value)q.set('price_list_id',$('priceList').value); if(uid)q.set('unit_id',String(uid));
      const r=await api('/api/enterprise/pricing/resolve?'+q.toString()); el.querySelector('.siPrice').value=Number(r.price||0);
    }catch(_){const p=ps.find(x=>x.id===pid);el.querySelector('.siPrice').value=Number(p?.selling_price||0)} calc();
  };
  const add=()=>{if(!ps.length)return;const el=document.createElement('div');el.className='sale-item';el.innerHTML=`<div class="sale-item-main"><label>Item<select class="siProduct"><option value="">Select item</option>${ps.map(x=>`<option value="${x.id}" data-type="${x.item_type}" data-price="${x.selling_price}">${esc(x.name)} — ${esc(x.sku||'')} — ${x.item_type==='service'?'service':'stock '+x.stock}</option>`).join('')}</select></label><span class="stock-hint"></span></div><label>Qty<input class="siQty" type="number" min="0.001" step="0.001" value="1"></label><label>Unit<select class="siUnit">${unitOptions}</select></label><label>Price<input class="siPrice" type="number" min="0" step="0.01" value="0"></label><strong class="siTotal">${money(0)}</strong><button type="button" class="danger removeSI">Remove</button>`;$('saleItems').appendChild(el);rows.push(el);const prod=el.querySelector('.siProduct');const sync=()=>{const x=ps.find(p=>p.id==prod.value);if(x){el.querySelector('.stock-hint').textContent=x.item_type==='service'?'Service — no stock required':`Available stock: ${x.stock}`;}priceFor(el)};prod.onchange=sync;el.querySelector('.siUnit').onchange=()=>priceFor(el);el.querySelector('.siPrice').oninput=calc;el.querySelector('.siQty').oninput=calc;el.querySelector('.removeSI').onclick=()=>{el.remove();rows=rows.filter(x=>x!==el);calc()};sync()};
  const calc=()=>{let subtotal=0,cost=0,below=false,valid=rows.length>0;rows.filter(r=>r.isConnected).forEach(r=>{const q=Number(r.querySelector('.siQty').value||0),p=Number(r.querySelector('.siPrice').value||0),prod=ps.find(x=>x.id==Number(r.querySelector('.siProduct').value));subtotal+=q*p;r.querySelector('.siTotal').textContent=money(q*p);if(!prod||q<=0||p<=0)valid=false;if(prod&&prod.item_type!=='service'&&q>Number(prod.stock||0)&&!$('warehouse').value)valid=false;if(prod&&p<Number(prod.buying_price||0)&&prod.item_type!=='service')below=true;cost+=prod&&prod.item_type!=='service'?q*Number(prod.buying_price||0):0});const discount=Math.max(0,Number($('disc').value||0)),net=Math.max(0,subtotal-discount);const opt=$('taxRate').selectedOptions[0];const rate=Number(opt?.dataset.rate||0)/100,inc=opt?.dataset.inclusive==='1';let tax=0,total=net;if(rate){if(inc){tax=(net*rate/(1+rate));total=net}else{tax=net*rate;total=net+tax}}const split=$('method').value==='split';let paid=split?[...document.querySelectorAll('.splitAmount')].reduce((a,x)=>a+Math.max(0,Number(x.value||0)),0):Math.max(0,Number($('paid').value||0));if(split)$('splitPaid').textContent=money(paid);if(total<cost)below=true;const override=Boolean($('belowCost')?.checked);$('saleSubtotal').textContent=money(subtotal);$('saleTax').textContent=money(tax);$('saleGrandTotal').textContent=money(total);$('saleBalance').textContent=money(Math.max(0,total-paid));$('saleEmpty').style.display=rows.length?'none':'';$('postSale').disabled=!valid||paid>total||(below&&!override);$('saleMessage').textContent=below&&!override?'Below-cost sale requires management approval.':'';$('saleMessage').className=below&&!override?'form-message error':'form-message';const ct=containers.find(x=>x.id==Number($('containerType').value)),issued=Number($('containersIssued').value||0),returned=Number($('containersReturned').value||0);$('containerDeposit').textContent=`Deposit: ${money(ct?Math.max(0,issued-returned)*Number(ct.deposit_value||0):0)}`;return {total,paid,valid,below,tax}};
  const updateBankVisibility=()=>{$('bankWrap').classList.toggle('hidden',!['bank'].includes($('method').value));$('splitWrap').classList.toggle('hidden',$('method').value!=='split');document.querySelectorAll('.splitBank').forEach(x=>x.classList.add('hidden'));calc()};
  $('addSaleItem').onclick=add;$('disc').oninput=calc;$('paid').oninput=calc;
  if(pendingCustomerId){const pc=cs.find(x=>x.id===pendingCustomerId);if(pc){$('customer').value=String(pendingCustomerId);rows.forEach(priceFor);}} pendingCustomerId=null;$('method').onchange=updateBankVisibility;$('customer').onchange=()=>rows.forEach(priceFor);$('priceList').onchange=()=>rows.forEach(priceFor);$('taxRate').onchange=calc;$('warehouse').onchange=calc;$('containerType').onchange=calc;$('containersIssued').oninput=calc;$('containersReturned').oninput=calc;$('clearSale').onclick=()=>loadPage('sales');if(shift)$('postSale').dataset.shift=shift.id;if(['owner','admin','manager'].includes(me?.role))$('belowCostWrap')?.classList.remove('hidden');$('belowCost')?.addEventListener('change',calc);
  document.querySelectorAll('.splitMethod').forEach(x=>x.onchange=e=>{const b=e.target.parentElement.querySelector('.splitBank');b.classList.toggle('hidden',e.target.value!=='bank');calc()});document.querySelectorAll('.splitAmount,.splitRef').forEach(x=>x.oninput=calc);
  $('saleF').onsubmit=async e=>{e.preventDefault();const st=calc(),msg=$('saleMessage');if(!st.valid||!rows.length){msg.textContent='Check items and quantities.';msg.className='form-message error';return}if(st.total<=0||st.paid>st.total){msg.textContent='Check discount and payment amount.';msg.className='form-message error';return}if(st.total>st.paid&&!$('customer').value){msg.textContent='Select a customer for a credit or partial sale.';msg.className='form-message error';return}if($('method').value==='bank'&&st.paid>0&&!$('bank').value){msg.textContent='Select a bank account.';msg.className='form-message error';return}
    let payments=[];if($('method').value==='split'){payments=[...document.querySelectorAll('#splitWrap .formgrid')].map(r=>({payment_method:r.querySelector('.splitMethod').value,amount:Number(r.querySelector('.splitAmount').value||0),bank_account_id:r.querySelector('.splitMethod').value==='bank'?(Number(r.querySelector('.splitBank').value||0)||null):null,reference:r.querySelector('.splitRef').value.trim()||null})).filter(x=>x.amount>0);if(!payments.length){msg.textContent='Add at least one split payment.';msg.className='form-message error';return}}
    else if(st.paid>0)payments=[{payment_method:$('method').value,amount:st.paid,bank_account_id:$('method').value==='bank'?(Number($('bank').value||0)||null):null,reference:$('ref').value.trim()||null}];
    const items=rows.filter(r=>r.isConnected).map(r=>({product_id:Number(r.querySelector('.siProduct').value),quantity:Number(r.querySelector('.siQty').value),unit_price:Number(r.querySelector('.siPrice').value),unit_id:r.querySelector('.siUnit').value?Number(r.querySelector('.siUnit').value):null}));
    const body={customer_id:$('customer').value?Number($('customer').value):null,items,discount:Number($('disc').value||0),paid:st.paid,payment_method:$('method').value,bank_account_id:$('bank').value?Number($('bank').value):null,reference:$('ref').value.trim()||null,allow_below_cost:Boolean($('belowCost')?.checked),container_type_id:$('containerType').value?Number($('containerType').value):null,containers_issued:Number($('containersIssued').value||0),containers_returned:Number($('containersReturned').value||0),branch_id:$('branch').value?Number($('branch').value):null,warehouse_id:$('warehouse').value?Number($('warehouse').value):null,price_list_id:$('priceList').value?Number($('priceList').value):null,shift_id:$('postSale').dataset.shift?Number($('postSale').dataset.shift):null,tax_rate_id:$('taxRate').value?Number($('taxRate').value):null,payments};
    const btn=$('postSale');btn.disabled=true;btn.textContent='Posting sale…';try{const result=await api('/api/sales',{method:'POST',body:JSON.stringify(body)});toast(`Sale ${result.invoice_no} posted successfully`);loadPage('sales')}catch(x){btn.disabled=false;btn.textContent='Complete Sale';msg.textContent=x.message||'Unable to complete sale.';msg.className='form-message error';toast(x.message||'Sale failed',true)}};add();updateBankVisibility();calc();salesHistory();
}

async function salesHistory(){
  const from=$('salesFrom')?.value||'',to=$('salesTo')?.value||'',status=$('salesStatus')?.value||'',customer=$('salesCustomer')?.value||'',q=$('salesSearch')?.value?.trim()||'';
  const params=new URLSearchParams();if(from)params.set('start_date',from);if(to)params.set('end_date',to);if(status)params.set('status',status);if(customer)params.set('customer_id',customer);if(q)params.set('q',q);
  try{const rows=await api('/api/sales?'+params.toString());$('salesHistoryTable').innerHTML=table(['Date','Invoice','Customer','Total','Paid','Balance','Status','Action'],rows.map(x=>[new Date(x.sale_date).toLocaleString(),x.invoice_no,x.customer_name,money(x.total),money(x.paid),money(x.balance),`<span class="success">${x.payment_status}</span>`,`<button onclick="viewSale(${x.id})">View</button>`]));}catch(x){toast(x.message,true)}
}
function salesAll(){if($('salesFrom'))$('salesFrom').value='';if($('salesTo'))$('salesTo').value='';salesHistory()}
async function downloadSalePdf(id,invoice){try{const r=await fetch(`${API}/api/sales/${id}/pdf`,{headers:{Authorization:`Bearer ${token}`}});if(!r.ok)throw Error('Invoice PDF export failed.');const blob=await r.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${invoice||'invoice'}.pdf`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){toast(e.message,true)}}
async function viewSale(id){try{const x=await api('/api/sales/'+id);const itemRows=x.items.map(i=>[i.sku,i.product_name,i.quantity,money(i.unit_price),money(i.line_total)]);$('content').innerHTML=`<div class="panel"><div style="display:flex;justify-content:space-between"><h3>Sale ${x.invoice_no}</h3><span><button onclick="downloadSalePdf(${x.id},'${x.invoice_no}')">Export PDF</button> <button onclick="loadPage('sales')">Back</button></span></div><p><b>Date:</b> ${new Date(x.sale_date).toLocaleString()} &nbsp; <b>Customer:</b> ${x.customer_name}</p>${table(['SKU','Product','Qty','Unit price','Total'],itemRows)}<div class="cards" style="margin-top:15px"><div class="stat"><small>Subtotal</small><strong>${money(x.subtotal)}</strong></div><div class="stat"><small>Discount</small><strong>${money(x.discount)}</strong></div><div class="stat"><small>Total</small><strong>${money(x.total)}</strong></div><div class="stat"><small>Paid</small><strong>${money(x.paid)}</strong></div><div class="stat"><small>Balance</small><strong>${money(x.balance)}</strong></div></div><p><b>Status:</b> ${x.payment_status} &nbsp; <b>Payment:</b> ${x.payment_method}</p>${x.balance>0&&x.customer_id?`<button onclick="recordCustomerPayment(${x.customer_id},${x.id},${x.balance})">Record payment</button>`:''}</div>`}catch(e){toast(e.message,true)}}
async function purchases(c){
  const [ps,ss,banks,warehouses,orders]=await Promise.all([api('/api/products'),api('/api/suppliers'),api('/api/banks'),api('/api/platform/warehouses'),api('/api/purchase-orders')]);
  c.innerHTML=`
  <div class="panel"><h3>Receive purchase</h3><form id="purF"><div class="formgrid"><input id="pinv" placeholder="Purchase invoice" required><select id="supplier"><option value="">No supplier</option>${ss.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')} </select><select id="pwarehouse">${warehouses.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><input id="ppaid" type="number" step="0.01" value="0" placeholder="Paid"><select id="pmethod"><option value="cash">Cash</option><option value="bank">Bank</option><option value="mobile_money">Mobile Money</option><option value="card">Card</option><option value="cheque">Cheque</option></select><select id="pbank" class="hidden"><option value="">Select bank</option>${banks.map(x=>`<option value="${x.id}">${esc(x.bank_name)} — ${esc(x.account_number)}</option>`).join('')}</select><input id="pref" placeholder="Reference"></div><div class="panel" style="margin-top:12px"><div style="display:flex;justify-content:space-between"><h4>Purchase items</h4><button type="button" id="addPurItem">+ Add item</button></div><div id="purItems"></div></div><button>Post purchase</button></form></div>
  <div class="panel" style="margin-top:15px"><div class="section-head"><div><h3>Purchase orders</h3><p class="muted">Create, approve and receive planned supplier orders without posting stock twice.</p></div></div><div class="grid" style="margin-top:12px"><form id="poForm"><select id="poSupplierSearch"><option value="">No supplier</option>${ss.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><select id="poWarehouse">${warehouses.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><input id="poExpected" type="date"><input id="poDiscount" type="number" min="0" step="0.01" value="0" placeholder="Discount"><input id="poNotes" placeholder="Notes"><div id="poLines"></div><button type="button" class="secondary" id="addPoItem">+ Add PO item</button><button>Create purchase order</button></form><div>${table(['PO','Supplier','Total','Status','Action'],orders.map(o=>[esc(o.po_no),esc(o.supplier_name),money(o.total),`<span class="badge">${esc(o.status)}</span>`,purchaseOrderActions(o)]))}</div></div></div>`;
  const add=()=>{const el=document.createElement('div');el.className='formgrid purchase-line';el.dataset.row='1';el.innerHTML=`<select class="piProduct">${ps.map(x=>`<option value="${x.id}" data-cost="${x.buying_price}">${esc(x.name)}${x.item_type==='service'?' — service':''}</option>`).join('')}</select><input class="piQty" type="number" min="0.001" step="0.001" value="1"><input class="piCost" type="number" min="0" step="0.01" value="${ps[0]?.buying_price||0}"><input class="piBatch" placeholder="Batch no. (optional)"><input class="piExpiry" type="date" title="Expiry (optional)"><button type="button" class="danger removePI">Remove</button>`;$('purItems').appendChild(el);const prod=el.querySelector('.piProduct'),cost=el.querySelector('.piCost');prod.onchange=()=>{const q=ps.find(x=>x.id==prod.value);cost.value=q?.buying_price||0};el.querySelector('.removePI').onclick=()=>el.remove()};
  $('addPurItem').onclick=add;$('pmethod').onchange=()=>{$('pbank').classList.toggle('hidden',$('pmethod').value!=='bank')};add();
  $('purF').onsubmit=async e=>{e.preventDefault();const items=[...document.querySelectorAll('#purItems [data-row]')].map(r=>({product_id:Number(r.querySelector('.piProduct').value),quantity:Number(r.querySelector('.piQty').value),unit_price:Number(r.querySelector('.piCost').value),batch_no:r.querySelector('.piBatch').value.trim()||null,expiry_date:r.querySelector('.piExpiry').value||null}));try{await api('/api/purchases',{method:'POST',body:JSON.stringify({invoice_no:$('pinv').value.trim(),supplier_id:$('supplier').value?Number($('supplier').value):null,warehouse_id:$('pwarehouse').value?Number($('pwarehouse').value):null,items,paid:Number($('ppaid').value||0),payment_method:$('pmethod').value,bank_account_id:$('pmethod').value==='bank'?Number($('pbank').value||0):null,reference:$('pref').value||null})});toast('Purchase posted');loadPage('purchases')}catch(x){toast(x.message,true)}};
  const addPo=()=>{const el=document.createElement('div');el.className='formgrid po-line';el.innerHTML=`<select class="poProduct">${ps.map(x=>`<option value="${x.id}" data-cost="${x.buying_price}">${esc(x.name)}</option>`).join('')}</select><input class="poQty" type="number" min="0.001" step="0.001" value="1"><input class="poPrice" type="number" min="0" step="0.01" value="${ps[0]?.buying_price||0}"><button type="button" class="danger">Remove</button>`;$('poLines').appendChild(el);el.querySelector('.poProduct').onchange=e=>el.querySelector('.poPrice').value=e.target.selectedOptions[0]?.dataset.cost||0;el.querySelector('button').onclick=()=>el.remove()};
  $('addPoItem').onclick=addPo;addPo();
  $('poForm').onsubmit=async e=>{e.preventDefault();const items=[...document.querySelectorAll('.po-line')].map(r=>({product_id:Number(r.querySelector('.poProduct').value),quantity:Number(r.querySelector('.poQty').value),unit_price:Number(r.querySelector('.poPrice').value)}));try{await api('/api/purchase-orders',{method:'POST',body:JSON.stringify({supplier_id:$('poSupplierSearch').value?Number($('poSupplierSearch').value):null,warehouse_id:$('poWarehouse').value?Number($('poWarehouse').value):null,expected_date:$('poExpected').value||null,discount:Number($('poDiscount').value||0),notes:$('poNotes').value.trim()||null,items})});toast('Purchase order created');purchases(c)}catch(x){toast(x.message,true)}};
}
function purchaseOrderActions(o){const parts=[];if(o.status==='draft')parts.push(`<button onclick="purchaseOrderStatus(${o.id},'approved')">Approve</button>`);if(o.status==='approved')parts.push(`<button onclick="receivePurchaseOrder(${o.id})">Receive</button>`);if(!['received','cancelled'].includes(o.status))parts.push(`<button class="secondary" onclick="purchaseOrderStatus(${o.id},'cancelled')">Cancel</button>`);return `<div class="row-actions">${parts.join(' ')||'—'}</div>`}
async function purchaseOrderStatus(id,status){try{await api(`/api/purchase-orders/${id}/status`,{method:'PUT',body:JSON.stringify({status})});toast('Purchase order updated');loadPage('purchases')}catch(e){toast(e.message,true)}}
async function receivePurchaseOrder(id){const invoice=prompt('Supplier invoice number:');if(!invoice)return;const paid=Number(prompt('Amount paid now (0 for credit):','0')||0);try{await api(`/api/purchase-orders/${id}/receive`,{method:'POST',body:JSON.stringify({invoice_no:invoice,paid,payment_method:paid?'cash':'credit',payments:[]})});toast('Purchase order received and stock posted');loadPage('purchases')}catch(e){toast(e.message,true)}}

async function expenses(c){const banks=await api('/api/banks');c.innerHTML=`<div class="panel"><h3>Record expense</h3><form id="ef"><div class="formgrid"><input id="ec" placeholder="Category e.g. fuel" required><input id="ea" type="number" step="0.01" placeholder="Amount" required><select id="em"><option value="cash">Cash</option><option value="bank">Bank</option><option value="mobile_money">Mobile Money</option><option value="card">Card</option><option value="cheque">Cheque</option></select><select id="ebank" class="hidden"><option value="">Select bank</option>${banks.map(x=>`<option value="${x.id}">${esc(x.bank_name)} — ${esc(x.account_number)}</option>`).join('')}</select><input id="er" placeholder="Reference"><input id="ed" placeholder="Description"><input id="edt" type="date"></div><button>Post expense</button></form></div>`;$('em').onchange=()=>{$('ebank').classList.toggle('hidden',$('em').value!=='bank')};$('ef').onsubmit=async e=>{e.preventDefault();try{await api('/api/expenses',{method:'POST',body:JSON.stringify({category:$('ec').value,amount:Number($('ea').value),payment_method:$('em').value,bank_account_id:$('em').value==='bank'?Number($('ebank').value||0):null,reference:$('er').value,description:$('ed').value,expense_date:$('edt').value||null})});toast('Expense posted');loadPage('expenses')}catch(x){toast(x.message,true)}}}

async function debts(c){
  const role=String(me?.role||'').toLowerCase();
  const canCustomers=['owner','admin','manager','accountant','salesperson','cashier'].includes(role);
  const canSuppliers=['owner','admin','manager','accountant','storekeeper'].includes(role);
  const canCustomerHistory=['owner','admin','manager','accountant','salesperson','cashier'].includes(role);
  const canSupplierHistory=['owner','admin','manager','accountant'].includes(role);
  const canReceiveCustomer=['owner','admin','manager','accountant','salesperson','cashier'].includes(role);
  const canPaySupplier=['owner','admin','accountant'].includes(role);
  const safeLoad=async path=>{try{return {rows:await api(path),error:null}}catch(e){return {rows:[],error:e.message||'Request failed'}}};
  const [customerLoad,supplierLoad,customerPaymentLoad,supplierPaymentLoad]=await Promise.all([
    canCustomers?safeLoad('/api/reports/customer-aging'):Promise.resolve({rows:[],error:null}),
    canSuppliers?safeLoad('/api/reports/supplier-aging'):Promise.resolve({rows:[],error:null}),
    canCustomerHistory?safeLoad('/api/customer-payments'):Promise.resolve({rows:[],error:null}),
    canSupplierHistory?safeLoad('/api/supplier-payments'):Promise.resolve({rows:[],error:null})
  ]);
  const customerRows=customerLoad.rows||[],supplierRows=supplierLoad.rows||[],customerPayments=customerPaymentLoad.rows||[],supplierPayments=supplierPaymentLoad.rows||[];
  const customerSummary=groupDebt(customerRows,'customer_id','customer_name');
  const supplierSummary=groupDebt(supplierRows,'supplier_id','supplier_name');
  const cards=[];
  if(canCustomers)cards.push(`<div class="stat"><small>Customers owing</small><strong>${customerLoad.error?'Unavailable':customerSummary.length}</strong></div><div class="stat"><small>Customer receivables</small><strong>${customerLoad.error?'—':money(customerSummary.reduce((a,x)=>a+Number(x.balance),0))}</strong></div>`);
  if(canSuppliers)cards.push(`<div class="stat"><small>Suppliers owing</small><strong>${supplierLoad.error?'Unavailable':supplierSummary.length}</strong></div><div class="stat"><small>Supplier payables</small><strong>${supplierLoad.error?'—':money(supplierSummary.reduce((a,x)=>a+Number(x.balance),0))}</strong></div>`);
  c.innerHTML=`<div class="panel"><div class="section-head"><div><h3>Debts & Payments</h3><p class="muted">Customer receivables are money owed to your business; supplier payables are money your business owes.</p></div><button class="secondary" onclick="loadPage('debts')">Refresh</button></div><div class="cards" style="margin-top:15px">${cards.join('')||'<div class="empty">Your role does not have access to debt records.</div>'}</div></div><div class="panel" style="margin-top:15px"><div class="toolbar">${canCustomers?'<button id="customerDebtTab">Customer debts · money owed to us</button>':''}${canSuppliers?'<button id="supplierDebtTab">Supplier debts · money we owe</button>':''}</div><div id="debtSection"></div></div>`;
  const alert=(msg)=>`<div class="notice notice-warning" role="status">${esc(msg)}</div>`;
  const renderCustomers=()=>{
    const err=customerLoad.error?alert('Customer debts could not be loaded: '+customerLoad.error):'';
    const paymentErr=customerPaymentLoad.error&&canCustomerHistory?alert('Payment history could not be loaded: '+customerPaymentLoad.error):'';
    $('debtSection').innerHTML=`${err}<div class="toolbar"><select id="debtCustomer"><option value="">All customers</option>${customerSummary.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><input id="debtSearch" placeholder="Search customer or invoice"><button onclick="filterCustomerDebts()">Search</button></div><div id="customerDebtSummary" style="margin-top:12px">${customerLoad.error?'<div class="empty">The customer balance summary is unavailable until the API/database issue is resolved.</div>':debtSummaryTable(customerSummary,'customer')}</div><div id="debtsTable" style="margin-top:12px">${customerLoad.error?'':debtsTable(customerRows,canReceiveCustomer)}</div>${canCustomerHistory?`<div class="panel" style="margin-top:15px"><h4>Customer payment history</h4>${paymentErr}<div id="customerPayments">${customerPaymentLoad.error?'':paymentHistoryTable(customerPayments,'customer')}</div></div>`:''}`;
    $('debtCustomer')?.addEventListener('change',filterCustomerDebts);
  };
  const renderSuppliers=()=>{
    const err=supplierLoad.error?alert('Supplier debts could not be loaded: '+supplierLoad.error):'';
    const paymentErr=supplierPaymentLoad.error&&canSupplierHistory?alert('Supplier payment history could not be loaded: '+supplierPaymentLoad.error):'';
    $('debtSection').innerHTML=`${err}<div class="toolbar"><select id="debtSupplier"><option value="">All suppliers</option>${supplierSummary.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><input id="supplierDebtSearch" placeholder="Search supplier or invoice"><button onclick="filterSupplierDebts()">Search</button></div><div id="supplierDebtSummary" style="margin-top:12px">${supplierLoad.error?'<div class="empty">The supplier balance summary is unavailable until the API/database issue is resolved.</div>':debtSummaryTable(supplierSummary,'supplier')}</div><div id="supplierDebtsTable" style="margin-top:12px">${supplierLoad.error?'':supplierDebtsTable(supplierRows,canPaySupplier)}</div>${canSupplierHistory?`<div class="panel" style="margin-top:15px"><h4>Supplier payment history</h4>${paymentErr}<div id="supplierPayments">${supplierPaymentLoad.error?'':paymentHistoryTable(supplierPayments,'supplier')}</div></div>`:'<p class="muted">Supplier payment history requires finance permissions.</p>'}`;
    $('debtSupplier')?.addEventListener('change',filterSupplierDebts);
  };
  if(canCustomers)$('customerDebtTab').onclick=renderCustomers;
  if(canSuppliers)$('supplierDebtTab').onclick=renderSuppliers;
  if(canCustomers)renderCustomers();else if(canSuppliers)renderSuppliers();
}
function groupDebt(rows,idKey,nameKey){const map=new Map();for(const x of rows){if(!x[idKey])continue;const id=Number(x[idKey]);const cur=map.get(id)||{id,name:x[nameKey],balance:0,total:0,paid:0,invoices:0};cur.balance+=Number(x.balance||0);cur.total+=Number(x.total||0);cur.paid+=Number(x.paid||0);cur.invoices+=1;map.set(id,cur)}return [...map.values()].sort((a,b)=>b.balance-a.balance)}
function debtSummaryTable(rows,side){return table([side==='customer'?'Customer':'Supplier','Invoices','Total','Paid','Outstanding','Action'],rows.map(x=>[esc(x.name),x.invoices,money(x.total),money(x.paid),money(x.balance),x.balance>0?`<button onclick="${side==='customer'?`focusCustomerDebt(${x.id})`:`focusSupplierDebt(${x.id})`}">View</button>`:'Paid']))}
function debtsTable(rows,allowPayment=true){return table(['Due','Customer','Invoice','Total','Paid','Balance','Age','Action'],rows.map(x=>[x.due_date||'Opening balance',esc(x.customer_name),esc(x.invoice_no),money(x.total),money(x.paid),money(x.balance),x.bucket,x.balance>0?(allowPayment?`<button onclick="recordCustomerPayment(${x.customer_id},${x.id??'null'},${x.balance})">Receive payment</button>`:'View only'):'Paid']))}
function supplierDebtsTable(rows,allowPayment=true){return table(['Due','Supplier','Invoice','Total','Paid','Balance','Age','Action'],rows.map(x=>[x.due_date||'Opening balance',esc(x.supplier_name),esc(x.invoice_no),money(x.total),money(x.paid),money(x.balance),x.bucket,x.balance>0?(allowPayment?`<button onclick="recordSupplierPayment(${x.supplier_id},${x.id??'null'},${x.balance})">Pay supplier</button>`:'View only'):'Paid']))}
function paymentHistoryTable(rows,side){return table(['Date',side==='customer'?'Customer':'Supplier','Invoice/Ref','Amount','Method','Reference'],rows.map(x=>[new Date(x.payment_date).toLocaleString(),esc(x[side==='customer'?'customer_name':'supplier_name']),x[side==='customer'?'sale_id':'purchase_id']?String(x[side==='customer'?'sale_id':'purchase_id']):'Opening balance',money(x.amount),x.payment_method,esc(x.reference||'')]))}
async function filterCustomerDebts(){const all=await api('/api/reports/customer-aging');const cid=$('debtCustomer')?.value||'',q=($('debtSearch')?.value||'').toLowerCase();const rows=all.filter(x=>(!cid||String(x.customer_id)===cid)&&(!q||String(x.customer_name).toLowerCase().includes(q)||String(x.invoice_no).toLowerCase().includes(q)));$('debtsTable').innerHTML=debtsTable(rows)}
async function filterSupplierDebts(){const all=await api('/api/reports/supplier-aging');const sid=$('debtSupplier')?.value||'',q=($('supplierDebtSearch')?.value||'').toLowerCase();const rows=all.filter(x=>(!sid||String(x.supplier_id)===sid)&&(!q||String(x.supplier_name).toLowerCase().includes(q)||String(x.invoice_no).toLowerCase().includes(q)));$('supplierDebtsTable').innerHTML=supplierDebtsTable(rows,['owner','admin','accountant'].includes(String(me?.role||'').toLowerCase()))}
function focusCustomerDebt(id){if($('debtCustomer')){$('debtCustomer').value=String(id);filterCustomerDebts();$('debtCustomer').scrollIntoView({behavior:'smooth',block:'center'})}}
function focusSupplierDebt(id){if($('debtSupplier')){$('debtSupplier').value=String(id);filterSupplierDebts();$('debtSupplier').scrollIntoView({behavior:'smooth',block:'center'})}}
async function recordCustomerPayment(customerId,saleId,balance){
 const amount=prompt(`Outstanding balance: ${money(balance)}\nAmount received:`,String(balance)); if(amount===null)return; const value=Number(amount);
 if(!value||value<=0||value>Number(balance)){toast('Invalid payment amount',true);return}
 const method=prompt('Payment method: cash or bank','cash'); if(method===null)return; const m=method.toLowerCase(); if(!['cash','bank'].includes(m)){toast('Payment method must be cash or bank',true);return}
 let bank_account_id=null; if(m==='bank'){const banks=await api('/api/banks'); if(!banks.length){toast('Add a bank account first.',true);return} const selected=prompt(`Choose bank account by ID:\n${banks.map(x=>`${x.id}: ${x.bank_name} — ${x.account_number}`).join('\n')}`,''); if(selected===null)return; bank_account_id=Number(selected); if(!bank_account_id){toast('Invalid bank account',true);return}}
 const reference=prompt('Reference (optional):',''); try{await api('/api/customer-payments',{method:'POST',body:JSON.stringify({customer_id:customerId,sale_id:saleId||null,amount:value,payment_method:m,bank_account_id,reference:reference||null})});toast('Customer payment recorded. Debt balance updated.');loadPage('debts')}catch(e){toast(e.message,true)}}
async function recordSupplierPayment(supplierId,purchaseId,balance){
 const amount=prompt(`Outstanding supplier balance: ${money(balance)}\nAmount paid:`,String(balance)); if(amount===null)return; const value=Number(amount);
 if(!value||value<=0||value>Number(balance)){toast('Invalid payment amount',true);return}
 const method=prompt('Payment method: cash or bank','cash'); if(method===null)return; const m=method.toLowerCase(); if(!['cash','bank'].includes(m)){toast('Payment method must be cash or bank',true);return}
 let bank_account_id=null; if(m==='bank'){const banks=await api('/api/banks'); if(!banks.length){toast('Add a bank account first.',true);return} const selected=prompt(`Choose bank account by ID:\n${banks.map(x=>`${x.id}: ${x.bank_name} — ${x.account_number}`).join('\n')}`,''); if(selected===null)return; bank_account_id=Number(selected); if(!bank_account_id){toast('Invalid bank account',true);return}}
 const reference=prompt('Reference (optional):',''); try{await api('/api/supplier-payments',{method:'POST',body:JSON.stringify({supplier_id:supplierId,purchase_id:purchaseId||null,amount:value,payment_method:m,bank_account_id,reference:reference||null})});toast('Supplier payment recorded. Payable balance updated.');loadPage('debts')}catch(e){toast(e.message,true)}}
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function chartSVG(type,rows,xKey,series,width=900,height=280){
  if(!rows.length)return '<div class="empty">No chart data for the selected period.</div>';
  const pad={l:55,r:20,t:25,b:45}, w=width-pad.l-pad.r,h=height-pad.t-pad.b;
  const vals=rows.flatMap(r=>series.map(s=>Number(r[s.key]||0))).filter(Number.isFinite); const max=Math.max(...vals,0); const min=Math.min(0,...vals); const span=(max-min)||1;
  const x=i=>pad.l+(rows.length===1?w/2:(i*w/(rows.length-1))); const y=v=>pad.t+(max-v)*h/span;
  let out=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(type)} chart" style="width:100%;height:auto;background:var(--panel,#fff);border:1px solid var(--border,#ddd);border-radius:10px">`;
  for(let i=0;i<=4;i++){const v=min+(span*i/4),yy=y(v);out+=`<line x1="${pad.l}" y1="${yy}" x2="${width-pad.r}" y2="${yy}" stroke="currentColor" opacity=".12"/><text x="${pad.l-8}" y="${yy+4}" text-anchor="end" font-size="10" fill="currentColor" opacity=".65">${money(v)}</text>`}
  series.forEach((ser,si)=>{const pts=rows.map((r,i)=>`${x(i)},${y(Number(r[ser.key]||0))}`).join(' ');if(type==='line'){out+=`<polyline fill="none" stroke="currentColor" stroke-width="3" points="${pts}" opacity="${1-si*.2}"/>`;rows.forEach((r,i)=>{out+=`<circle cx="${x(i)}" cy="${y(Number(r[ser.key]||0))}" r="3.5" fill="currentColor" opacity="${1-si*.2}"/>`})}});
  rows.forEach((r,i)=>{let label=String(r[xKey]??'');if(label.length>12)label=label.slice(0,12)+'…';out+=`<text x="${x(i)}" y="${height-15}" text-anchor="middle" font-size="10" fill="currentColor" opacity=".7">${esc(label)}</text>`});
  out+='</svg>'; return out;
}
function barSVG(rows,xKey,valueKey,width=900,height=280){
  if(!rows.length)return '<div class="empty">No chart data for the selected period.</div>';
  const top=25,bottom=45,left=55,right=20,w=width-left-right,h=height-top-bottom,max=Math.max(...rows.map(r=>Number(r[valueKey]||0)),0)||1;
  const bw=Math.max(8,(w/rows.length)*.65); let out=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="bar chart" style="width:100%;height:auto;background:var(--panel,#fff);border:1px solid var(--border,#ddd);border-radius:10px">`;
  for(let i=0;i<=4;i++){const v=max*i/4,yy=top+h-(v/max)*h;out+=`<line x1="${left}" y1="${yy}" x2="${width-right}" y2="${yy}" stroke="currentColor" opacity=".12"/><text x="${left-8}" y="${yy+4}" text-anchor="end" font-size="10" fill="currentColor" opacity=".65">${money(v)}</text>`}
  rows.forEach((r,i)=>{const v=Math.max(0,Number(r[valueKey]||0)),bh=v/max*h,xx=left+i*w/rows.length+(w/rows.length-bw)/2,yy=top+h-bh;let label=String(r[xKey]??'');if(label.length>12)label=label.slice(0,12)+'…';out+=`<rect x="${xx}" y="${yy}" width="${bw}" height="${bh}" rx="4" fill="currentColor" opacity=".78"><title>${esc(r[xKey])}: ${money(v)}</title></rect><text x="${xx+bw/2}" y="${height-15}" text-anchor="middle" font-size="10" fill="currentColor" opacity=".7">${esc(label)}</text>`}); return out+'</svg>';
}
async function reports(c){
  const today=new Date().toLocaleDateString('en-CA',{timeZone:'Africa/Dar_es_Salaam'}); const first=today.slice(0,8)+'01';
  c.innerHTML=`<div class="panel"><h3>Reports & Analytics</h3><div class="toolbar"><select id="reportPeriod"><option value="today">Today</option><option value="week">This week</option><option value="month" selected>This month</option><option value="3">3 months</option><option value="6">6 months</option><option value="12">12 months</option><option value="custom">Custom</option></select><input id="reportFrom" type="date" value="${first}"><input id="reportTo" type="date" value="${today}"><select id="reportType"><option value="summary">Summary</option><option value="sales">Sales by day</option><option value="purchases">Purchases by day</option><option value="expenses">Expenses</option><option value="product-sales">Product sales</option><option value="stock">Stock</option><option value="margins">Margins</option><option value="cash-book">Cash book</option><option value="bank-statement">Bank statement</option><option value="stock-ledger">Stock ledger</option><option value="audit-log">Audit log</option><option value="inventory-valuation">Inventory valuation</option><option value="tax-summary">Tax summary</option></select><button id="runReport">Run report</button><button id="pdfReport">Export PDF</button><button id="excelReport">Export Excel</button></div><div id="reportCards" class="cards" style="margin-top:15px"></div><div id="reportChart" style="margin-top:15px"></div><div id="reportTable" style="margin-top:15px"></div></div>`;
  const period=$('reportPeriod'),from=$('reportFrom'),to=$('reportTo'); period.onchange=()=>{const d=new Date();let start=new Date(d);if(period.value==='today')start=new Date(d);else if(period.value==='week')start.setDate(d.getDate()-6);else if(period.value==='month')start=new Date(d.getFullYear(),d.getMonth(),1);else if(['3','6','12'].includes(period.value))start.setMonth(d.getMonth()-Number(period.value)+1);from.value=start.toLocaleDateString('en-CA');to.value=today;};
  const run=async()=>{if(!from.value||!to.value||from.value>to.value){toast('Invalid report dates',true);return}const type=$('reportType').value;try{
    if(type==='inventory-valuation'){const v=await api('/api/enterprise/inventory/valuation');const vr=v.rows||v||[];const vkeys=vr.length?Object.keys(vr[0]):[];$('reportCards').innerHTML=`<div class="stat"><small>Total valuation</small><strong>${money(v.total_value||0)}</strong></div><div class="stat"><small>Items valued</small><strong>${vr.length}</strong></div>`;$('reportChart').innerHTML='';$('reportTable').innerHTML=table(vkeys,vr.map(r=>vkeys.map(k=>r[k])));return}
    if(type==='tax-summary'){const t=await api(`/api/enterprise/reports/tax-summary?start_date=${from.value}&end_date=${to.value}`);const tr=t.rows||t||[];const tkeys=tr.length?Object.keys(tr[0]):[];$('reportCards').innerHTML=`<div class="stat"><small>Taxable sales</small><strong>${money(t.total_taxable_sales||0)}</strong></div><div class="stat"><small>Tax collected</small><strong>${money(t.total_tax||0)}</strong></div>`;$('reportChart').innerHTML='';$('reportTable').innerHTML=table(tkeys,tr.map(r=>tkeys.map(k=>r[k])));return}
    const d=await api(`/api/reports/${type}?start_date=${from.value}&end_date=${to.value}`);$('reportChart').innerHTML='';if(type==='summary'){const cards=[['Sales',d.sales],['Returns',d.sales_returns],['Net sales',d.net_sales],['Gross profit',d.gross_profit],['Margin %',Number(d.margin_percent||0).toFixed(2)+'%'],['Expenses',d.expenses],['Net profit',d.net_profit]];$('reportCards').innerHTML=cards.map(x=>`<div class="stat"><small>${x[0]}</small><strong>${typeof x[1]==='string'&&x[1].includes('%')?x[1]:money(x[1])}</strong></div>`).join('');$('reportChart').innerHTML='<div class="empty">Choose Sales, Purchases, Expenses or Product sales to display an analytics chart.</div>';$('reportTable').innerHTML='<div class="empty">Summary loaded. Choose a detailed report to view its table.</div>';return}
    const rows=Array.isArray(d)?d:(d.products||[d]); const keys=rows.length?Object.keys(rows[0]):[]; $('reportCards').innerHTML='';
    if(type==='sales'&&rows.length)$('reportChart').innerHTML=chartSVG('Sales trend',rows,'day',[{key:'sales',label:'Sales'}]);
    else if(type==='purchases'&&rows.length)$('reportChart').innerHTML=chartSVG('Purchases trend',rows,'day',[{key:'purchases',label:'Purchases'}]);
    else if(type==='expenses'&&rows.length)$('reportChart').innerHTML=barSVG(rows.slice(0,20),'category','amount');
    else if(type==='product-sales'&&rows.length)$('reportChart').innerHTML=barSVG(rows.slice(0,15),'name','sales');
    else if(type==='margins'&&d.products?.length)$('reportChart').innerHTML=barSVG(d.products.slice(0,15),'name','gross_profit');
    $('reportTable').innerHTML=table(keys,rows.map(r=>keys.map(k=>r[k])));
  }catch(e){toast(e.message,true)}};
  $('runReport').onclick=run; const downloadReport=async(ext)=>{try{const r=await fetch(`${API}/api/reports/export/${ext}?report=${encodeURIComponent($('reportType').value)}&start_date=${from.value}&end_date=${to.value}`,{headers:{Authorization:`Bearer ${token}`}});if(!r.ok)throw Error('Export failed: HTTP '+r.status);const blob=await r.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`codezone-${$('reportType').value}.${ext==='pdf'?'pdf':'xlsx'}`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){toast(e.message,true)}}; $('pdfReport').onclick=()=>downloadReport('pdf'); $('excelReport').onclick=()=>downloadReport('excel'); run();
}

function table(head,rows){if(!rows.length)return '<div class="empty">No records yet.</div>';return `<div class="tablewrap"><table class="table"><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v??''}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
