  $('wf').onsubmit=async e=>{e.preventDefault();try{await api('/api/platform/warehouses',{method:'POST',body:JSON.stringify({code:$('wcode').value.trim(),name:$('wname').value.trim(),branch_id:$('wbranch').value?Number($('wbranch').value):null,is_default:$('wdef').checked})});toast('Warehouse added');locationsPage(c)}catch(x){toast(x.message,true)}};
