async function shiftPage(c){
  const [s,branches]=await Promise.all([api('/api/platform/shift/current'),api('/api/platform/branches').catch(()=>[])])
  const branchOptions=(branches||[]).map(b=>`<option value="${b.id}" ${s?.branch_id===b.id?'selected':''}>${esc(b.name)}</option>`).join('');
  if(s){
    const byMethod=(s.payments_by_method||[]).map(x=>`<div class="mini-stat"><small>${esc(x.method)}</small><strong>${money(x.amount)}</strong></div>`).join('');
    c.innerHTML=`<div class="shift-page"><div class="shift-hero panel"><div><span class="eyebrow">REGISTER CONTROL</span><h3>Shift is open</h3><p class="muted">Opened by ${esc(s.user_name||'current cashier')} · ${new Date(s.opened_at).toLocaleString()}</p></div><span class="shift-status-good">OPEN</span></div><div class="metric-grid"><div class="metric-card primary"><div class="metric-label"><span>Opening cash</span></div><strong>${money(s.opening_cash)}</strong><small>Starting float</small></div><div class="metric-card"><div class="metric-label"><span>Sales</span></div><strong>${s.sales_count||0}</strong><small>${money(s.sales_total||0)} total posted</small></div><div class="metric-card"><div class="metric-label"><span>Expected cash</span></div><strong>${money(s.expected_cash||0)}</strong><small>Opening float + cash movements</small></div><div class="metric-card"><div class="metric-label"><span>Cash difference</span></div><strong>${money(s.running_difference||0)}</strong><small>Based on current count, if available</small></div></div><div class="dashboard-grid-two"><section class="panel"><div class="section-head"><div><h3>Payments this shift</h3><span class="muted">A quick view before you close the drawer.</span></div></div><div class="mini-stat-grid">${byMethod||'<div class="empty">No payments recorded yet.</div>'}</div></section><section class="panel"><h3>Open & close discipline</h3><p class="muted">Open your shift when you arrive. Record every cash-in or cash-out. At closing, count the drawer, review the variance and close the shift before leaving the shop.</p><form id="sf"><label>Counted cash<input id="scount" type="number" step="0.01" min="0" placeholder="Enter physical cash counted" required></label><textarea id="snotes" placeholder="Closing notes (optional)"></textarea><button class="primary-action">Close shift & reconcile</button></form></section></div></div>`;
    $('sf').onsubmit=async e=>{e.preventDefault();const counted=Number($('scount').value||0);if(!confirm(`Close shift with counted cash ${money(counted)}?`))return;try{const r=await api(`/api/platform/shift/${s.id}/close`,{method:'POST',body:JSON.stringify({counted_cash:counted,notes:$('snotes').value.trim()||null})});toast(`Shift closed. Difference: ${money(r.difference)}`);await refreshOperationalHeader();shiftPage(c)}catch(x){toast(x.message,true)}}
  } else {
    const defaultBranch=(branches||[]).find(b=>b.is_default)||((branches||[])[0]||null);
    c.innerHTML=`<div class="shift-page"><div class="shift-required panel"><div class="shift-required-icon">◷</div><div><span class="eyebrow">START YOUR DAY</span><h3>Open shift</h3><p class="muted">Open a register shift when you arrive at the shop. You must have an open shift before posting sales.</p><form id="sof"><div class="formgrid"><label>Branch<select id="shiftBranch"><option value="">Use default branch</option>${branchOptions}</select></label><label>Opening cash / float<input id="sopen" type="number" step="0.01" min="0" placeholder="Opening cash" value="0"></label></div><button class="primary-action">Open shift & start selling</button></form></div></div><div class="panel"><h3>End-of-day routine</h3><div class="routine-list"><div><strong>1. Count cash</strong><span>Count physical notes and coins.</span></div><div><strong>2. Review payment totals</strong><span>Compare cash, bank, mobile money and other payments.</span></div><div><strong>3. Close shift</strong><span>Record variance and leave an audit trail.</span></div></div></div></div>`;
    $('sof').onsubmit=async e=>{e.preventDefault();try{await api('/api/platform/shift/open',{method:'POST',body:JSON.stringify({branch_id:$('shiftBranch').value?Number($('shiftBranch').value):(defaultBranch?.id||null),opening_cash:Number($('sopen').value||0)})});toast('Shift opened. You can start selling now.');await refreshOperationalHeader();shiftPage(c)}catch(x){toast(x.message,true)}}
  }
}

