async function ordersPage(c){
  const [quotes,orders,customers,products]=await Promise.all([api('/api/quotes'),api('/api/sales-orders'),api('/api/customers'),api('/api/products')]);
  c.innerHTML=`<div class="grid">
    <div class="panel"><div class="section-head"><div><h3>Create quotation</h3><p class="muted">Build a customer-ready quote before committing stock.</p></div></div>
      <form id="qf"><div class="formgrid"><select id="qCustomer"><option value="">Walk-in / no customer</option>${customers.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><input id="qValid" type="date"></div>
      <div id="qLines"></div><button type="button" class="secondary" id="qAdd">+ Add line</button><input id="qDiscount" type="number" step="0.01" min="0" placeholder="Discount"><textarea id="qNotes" placeholder="Notes / terms"></textarea><button>Create quotation</button></form>
    </div>
    <div class="panel"><div class="section-head"><div><h3>Quotations</h3><p class="muted">Draft, send, accept, reject and convert.</p></div></div>${table(['Quote','Customer','Total','Status','Actions'],quotes.map(q=>[esc(q.quote_no),esc(q.customer_name),money(q.total),`<span class="badge">${esc(q.status)}</span>`,quoteActions(q)]))}</div>
  </div>
  <div class="panel" style="margin-top:15px"><div class="section-head"><div><h3>Sales orders</h3><p class="muted">Confirmed orders become invoices only when fulfilled through the sales workflow.</p></div></div>${table(['Order','Customer','Total','Status','Action'],orders.map(o=>[esc(o.order_no),esc(o.customer_name),money(o.total),`<span class="badge">${esc(o.status)}</span>`,orderActions(o)]))}</div>`;
  const lineHtml=()=>`<div class="order-line"><select class="ql-product"><option value="">Select product/service</option>${products.map(x=>`<option value="${x.id}" data-price="${x.selling_price}">${esc(x.name)} — ${money(x.selling_price)}</option>`).join('')}</select><input class="ql-qty" type="number" min="0.001" step="0.001" value="1"><input class="ql-price" type="number" min="0.01" step="0.01" placeholder="Unit price"><button type="button" class="danger q-remove">×</button></div>`;
  const addLine=()=>{const wrap=$('qLines');const d=document.createElement('div');d.innerHTML=lineHtml();const line=d.firstElementChild;wrap.appendChild(line);line.querySelector('.ql-product').onchange=e=>{const opt=e.target.selectedOptions[0];line.querySelector('.ql-price').value=opt?.dataset.price||''};line.querySelector('.q-remove').onclick=()=>line.remove()};
  $('qAdd').onclick=addLine; addLine();
  $('qf').onsubmit=async e=>{e.preventDefault();const items=[...document.querySelectorAll('.order-line')].map(line=>({product_id:Number(line.querySelector('.ql-product').value),quantity:Number(line.querySelector('.ql-qty').value),unit_price:Number(line.querySelector('.ql-price').value)}));if(items.some(x=>!x.product_id||!x.unit_price)){toast('Select a product and valid price for every line.',true);return}try{await api('/api/quotes',{method:'POST',body:JSON.stringify({customer_id:$('qCustomer').value?Number($('qCustomer').value):null,valid_until:$('qValid').value||null,discount:Number($('qDiscount').value||0),notes:$('qNotes').value.trim()||null,items})});toast('Quotation created');ordersPage(c)}catch(x){toast(x.message,true)}};
}
function quoteActions(q){
  const parts=[];
  if(q.status==='draft') parts.push(`<button class="secondary" onclick="quoteStatus(${q.id},'sent')">Send</button>`);
  if(q.status==='sent'||q.status==='draft') parts.push(`<button onclick="quoteStatus(${q.id},'accepted')">Accept</button>`);
  if(q.status==='sent'||q.status==='draft') parts.push(`<button class="secondary" onclick="quoteStatus(${q.id},'rejected')">Reject</button>`);
  if(q.status==='sent'||q.status==='accepted') parts.push(`<button onclick="quoteToOrder(${q.id})">Convert to order</button>`);
  return `<div class="row-actions">${parts.join(' ')||'—'}</div>`;
}
function orderActions(o){
  const parts=[];
  if(o.status==='draft') parts.push(`<button onclick="orderStatus(${o.id},'confirmed')">Confirm</button>`);
  if(o.status==='confirmed') parts.push(`<button onclick="orderToSale(${o.id},'0','cash')">Invoice / Sell</button>`);
  if(o.status!=='fulfilled'&&o.status!=='cancelled') parts.push(`<button class="secondary" onclick="orderStatus(${o.id},'cancelled')">Cancel</button>`);
  return `<div class="row-actions">${parts.join(' ')||'—'}</div>`;
}
async function quoteStatus(id,status){try{await api(`/api/quotes/${id}/status`,{method:'PUT',body:JSON.stringify({status})});toast('Quotation status updated');loadPage('orders')}catch(e){toast(e.message,true)}}
