let __czMessagesTab='messages';
window.__czMessagesRenderSeq=window.__czMessagesRenderSeq||0;
window.__czConversationFilter=window.__czConversationFilter||'all';
window.__czComposeNew=window.__czComposeNew||false;
window.__czShowInboxOnly=window.__czShowInboxOnly||false;
function openCommunicationTab(tab){
  __czMessagesTab=tab;window.__czCommunicationTab=tab;
  if(tab==='messages'){window.__czTaskConversationId=null;window.__czComposeNew=false;window.__czShowInboxOnly=false;}
  loadPage('messages');
}
function openTeamConversation(id){window.__czConversationId=Number(id);window.__czComposeNew=false;window.__czShowInboxOnly=false;__czMessagesTab='messages';window.__czCommunicationTab='messages';loadPage('messages');}
function showTeamConversationInbox(){window.__czConversationId=null;window.__czComposeNew=false;window.__czShowInboxOnly=true;loadPage('messages');}
function teamConversationTitle(conversation){
  const others=(conversation?.participants||[]).filter(p=>Number(p.id)!==Number(me?.id));
  if(conversation?.kind==='direct')return others[0]?.name||conversation?.subject||'Direct message';
  return conversation?.subject||others.map(p=>p.name).join(', ')||'Group conversation';
}
function teamConversationInitials(conversation){
  const title=teamConversationTitle(conversation).trim();
  return title.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'C';
}
function applyConversationFilters(){
  const input=$('conversationSearch');const query=(input?.value||'').trim().toLocaleLowerCase();
  const filter=window.__czConversationFilter||'all';
  document.querySelectorAll('.conversation-row').forEach(row=>{
    const text=(row.dataset.search||'').toLocaleLowerCase();
    const kind=row.dataset.kind||'direct';
    const unread=Number(row.dataset.unread||0)>0;
    const matchesQuery=!query||text.includes(query);
    const matchesFilter=filter==='all'||(filter==='unread'&&unread)||(filter==='direct'&&kind==='direct')||(filter==='groups'&&kind==='group');
    row.hidden=!(matchesQuery&&matchesFilter);
  });
  document.querySelectorAll('[data-chat-filter]').forEach(button=>button.classList.toggle('active',button.dataset.chatFilter===filter));
  const empty=$('conversationFilterEmpty');if(empty)empty.classList.toggle('hidden',!!document.querySelector('.conversation-row:not([hidden])'));
}
function setConversationFilter(filter){window.__czConversationFilter=filter;applyConversationFilters();}
function teamMessageLink(m){return m.linked_entity_type?`<div class="muted" style="font-size:12px;margin-top:5px">Linked record: ${esc(m.linked_entity_type)} #${m.linked_entity_id}</div>`:''}
async function messagesPage(c){
  const renderSeq=++window.__czMessagesRenderSeq;
  const tab=window.__czCommunicationTab||__czMessagesTab||'messages';
  __czMessagesTab=tab;
  const nav=`<div class="section-head"><div><h3>Messages</h3><p class="muted">Every person or group has its own conversation. Open a chat to see only that thread.</p></div><div class="row-actions"><button class="${tab==='messages'?'':'secondary'}" onclick="openCommunicationTab('messages')">Messages</button><button class="${tab==='tasks'?'':'secondary'}" onclick="openCommunicationTab('tasks')">Tasks</button></div></div>`;
  if(tab==='tasks'){
    const [tasks,users,branches,allConversations]=await Promise.all([api('/api/communications/tasks'),api('/api/communications/users'),api('/api/platform/branches').catch(()=>[]),api('/api/communications/conversations')]);
    if(renderSeq!==window.__czMessagesRenderSeq)return;
    const taskConversation=Number(window.__czTaskConversationId||window.__czConversationId||0);
    const linkedConversation=allConversations.find(x=>x.id===taskConversation)||null;
    const taskUsers=linkedConversation?linkedConversation.participants:[{id:me.id,name:me.name,role:me.role},...users];
    c.innerHTML=`<div class="panel">${nav}<div class="grid"><div class="panel"><h3>Assign a task</h3><form id="teamTaskForm"><input id="teamTaskTitle" placeholder="Task title" required minlength="2" maxlength="180"><textarea id="teamTaskDescription" placeholder="Instructions / details"></textarea><select id="teamTaskAssignee" required>${taskUsers.map(u=>`<option value="${u.id}">${esc(u.name)} — ${esc(u.role)}</option>`).join('')}</select><div class="formgrid"><select id="teamTaskPriority"><option value="normal">Normal priority</option><option value="low">Low</option><option value="high">High</option><option value="urgent">Urgent</option></select><input id="teamTaskDue" type="datetime-local" aria-label="Due date"></div><select id="teamTaskBranch"><option value="">No branch context</option>${branches.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select><button type="submit">Assign task</button></form></div><div class="panel"><h3>My tasks</h3>${tasks.length?table(['Task','Assigned to','Priority','Due','Status','Action'],tasks.map(t=>[`<strong>${esc(t.title)}</strong><small>${esc(t.description||'')}${t.conversation_id?` · Conversation #${t.conversation_id}`:''}</small>`,esc(t.assignee_name),`<span class="badge">${esc(t.priority)}</span>`,t.due_at?new Date(t.due_at).toLocaleString():'No deadline',`<span class="badge">${esc(t.status)}</span>`,t.status==='done'||t.status==='cancelled'?'—':`<select id="taskStatus${t.id}" onchange="updateTeamTask(${t.id},this.value)"><option value="${esc(t.status)}" selected>${esc(t.status)}</option>${['open','in_progress','blocked','done','cancelled'].filter(s=>s!==t.status).map(s=>`<option value="${s}">${s.replace('_',' ')}</option>`).join('')}</select>`])):'<div class="empty">No tasks have been assigned to you or created by you yet.</div>'}</div></div></div>`;
    $('teamTaskForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/communications/tasks',{method:'POST',body:JSON.stringify({title:$('teamTaskTitle').value.trim(),description:$('teamTaskDescription').value.trim()||null,assigned_to:Number($('teamTaskAssignee').value),priority:$('teamTaskPriority').value,due_at:$('teamTaskDue').value?new Date($('teamTaskDue').value).toISOString():null,branch_id:$('teamTaskBranch').value?Number($('teamTaskBranch').value):null,conversation_id:taskConversation||null})});toast('Task assigned');messagesPage(c)}catch(e){toast(e.message,true)}};
    return;
  }
  let [conversations,users]=await Promise.all([api('/api/communications/conversations'),api('/api/communications/users')]);
  if(renderSeq!==window.__czMessagesRenderSeq)return;
  let selectedId=Number(window.__czConversationId||0);
  const composeNew=window.__czComposeNew===true;
  const showInboxOnly=window.__czShowInboxOnly===true;
  if(!composeNew&&!showInboxOnly&&(!selectedId||!conversations.some(x=>Number(x.id)===selectedId))&&conversations.length){selectedId=Number(conversations[0].id);window.__czConversationId=selectedId;}
  let selected=conversations.find(x=>Number(x.id)===selectedId)||null;
  let thread=[];
  if(selected){
    const rows=await api(`/api/communications/conversations/${selected.id}/messages`);
    if(renderSeq!==window.__czMessagesRenderSeq)return;
    // Enforce a strict UI boundary even if a faulty/stale response ever contains a different thread.
    thread=(Array.isArray(rows)?rows:[]).filter(m=>Number(m.conversation_id)===Number(selected.id));
    conversations=await api('/api/communications/conversations'); // refresh unread counters after marking this thread read
    if(renderSeq!==window.__czMessagesRenderSeq)return;
    selected=conversations.find(x=>Number(x.id)===selectedId)||selected;
  }
  await refreshMessageBadge();
  if(renderSeq!==window.__czMessagesRenderSeq)return;
  const rowMarkup=conversations.map(x=>{
    const title=teamConversationTitle(x);const other=x.last_message?.sender_id===me.id?'You':(x.participants||[]).find(p=>Number(p.id)===Number(x.last_message?.sender_id))?.name||'';
    const preview=x.last_message?`${other?other+': ':''}${String(x.last_message.body||'').replace(/\s+/g,' ').trim()}`:'No messages yet';
    const unread=Number(x.unread_count||0);const kind=x.kind==='group'?'group':'direct';
    const searchText=[title,preview,...(x.participants||[]).map(p=>p.name)].join(' ').toLocaleLowerCase();
    const time=x.updated_at?new Date(x.updated_at).toLocaleString():'—';
    return `<button type="button" class="conversation-row ${Number(x.id)===selectedId?'selected':''}" data-conversation-id="${x.id}" data-kind="${kind}" data-unread="${unread}" data-search="${esc(searchText)}" onclick="openTeamConversation(${x.id})"><span class="conversation-avatar">${esc(teamConversationInitials(x))}</span><span class="conversation-row-main"><span class="conversation-row-top"><strong>${esc(title)}</strong><small>${esc(time)}</small></span><small class="conversation-preview">${esc(preview)}</small><span class="conversation-row-bottom"><span class="conversation-kind">${kind==='group'?'Group chat':'Direct message'}</span>${unread?`<span class="conversation-unread">${unread>99?'99+':unread}</span>`:''}</span></span></button>`;
  }).join('');
  const people=selected?.participants||[];
  const title=selected?teamConversationTitle(selected):'';
  const messages=thread.map(m=>`<article class="team-message ${Number(m.sender_id)===Number(me.id)?'mine':''}"><div class="team-message-head"><strong>${esc(m.sender_name)}</strong><small>${new Date(m.created_at).toLocaleString()}</small></div><div class="team-message-body">${esc(m.body).replace(/\n/g,'<br>')}</div>${teamMessageLink(m)}${Number(m.sender_id)===Number(me.id)?`<small class="muted">Delivered ${m.delivered_to?.length||0}/${Math.max(0,people.filter(p=>Number(p.id)!==Number(me.id)).length)} · Read ${m.read_by?.length||0}/${Math.max(0,people.filter(p=>Number(p.id)!==Number(me.id)).length)}</small>`:''}</article>`).join('');
  const threadPanel=selected?`<div class="team-thread-header"><button type="button" class="secondary team-back-to-inbox" onclick="showTeamConversationInbox()">← Chats</button><span class="conversation-avatar large">${esc(teamConversationInitials(selected))}</span><div class="team-thread-title"><h3>${esc(title)}</h3><p class="muted">${selected.kind==='group'?'Group conversation':'Direct conversation'} · ${people.map(p=>`${esc(p.name)} (${esc(p.role)})`).join(' · ')}</p></div><button class="secondary" onclick="createTaskFromConversation(${selected.id})">Create task</button></div><div class="team-thread-identity">Showing messages only from <strong>${esc(title)}</strong>.</div><div class="team-message-list">${messages||'<div class="empty">No messages in this conversation yet. Write the first reply below.</div>'}</div><form id="teamReplyForm"><textarea id="teamReplyBody" placeholder="Message ${esc(title)}…" required maxlength="10000"></textarea><details class="message-link-details"><summary>Link a business record (optional)</summary><div class="formgrid"><select id="teamReplyLinkType"><option value="">No linked record</option><option value="sale">Sale / invoice</option><option value="purchase">Purchase</option><option value="purchase_order">Purchase order</option><option value="product">Product</option><option value="stock_transfer">Stock transfer</option><option value="shift">Shift</option><option value="expense">Expense</option><option value="customer">Customer</option><option value="supplier">Supplier</option><option value="service_order">Service job</option></select><input id="teamReplyLinkId" type="number" min="1" placeholder="Record ID (optional)"></div></details><button type="submit">Send message</button></form>`:composeNew?`<div class="team-compose-header"><button type="button" class="secondary team-back-to-inbox" onclick="showTeamConversationInbox()">← Chats</button><h3>New message</h3><p class="muted">Choose one colleague for a private chat, or choose Group chat to message several people.</p></div><div id="newConversationHost"></div>`:`<div class="team-empty-thread"><div class="conversation-avatar large">✉</div><h3>Choose a conversation</h3><p>Pick Juma or another chat from the list. Only that conversation will appear here.</p><button onclick="startNewTeamConversation()">New message</button></div>`;
  c.innerHTML=`<div class="panel team-communications-page">${nav}<div class="team-communication-layout ${selected?'has-selected':''} ${composeNew?'is-composing':''} ${showInboxOnly?'inbox-only':''}"><aside class="team-conversation-list"><div class="conversation-list-header"><div><h3>Chats</h3><p class="muted">${conversations.length} conversation${conversations.length===1?'':'s'}</p></div><button onclick="startNewTeamConversation()">+ New message</button></div><input id="conversationSearch" class="conversation-search" type="search" placeholder="Search people or messages…" aria-label="Search conversations"><div class="conversation-filters"><button type="button" data-chat-filter="all" onclick="setConversationFilter('all')">All</button><button type="button" data-chat-filter="unread" onclick="setConversationFilter('unread')">Unread</button><button type="button" data-chat-filter="direct" onclick="setConversationFilter('direct')">Direct</button><button type="button" data-chat-filter="groups" onclick="setConversationFilter('groups')">Groups</button></div><div class="conversation-list-scroll">${rowMarkup||'<div class="empty">No conversations yet. Start a chat with a colleague.</div>'}<div id="conversationFilterEmpty" class="empty hidden">No chats match this filter.</div></div></aside><section class="team-thread">${threadPanel}</section></div></div>`;
  $('conversationSearch')?.addEventListener('input',applyConversationFilters);
  applyConversationFilters();
  if(selected){
    $('teamReplyForm').onsubmit=async e=>{e.preventDefault();const body=$('teamReplyBody').value.trim();if(!body)return;try{const kind=$('teamReplyLinkType').value||null;const rawId=$('teamReplyLinkId').value;await api(`/api/communications/conversations/${selected.id}/messages`,{method:'POST',body:JSON.stringify({body,linked_entity_type:kind,linked_entity_id:kind&&rawId?Number(rawId):null})});await messagesPage(c);const list=$('content')?.querySelector('.team-message-list');if(list)list.scrollTop=list.scrollHeight;}catch(e){toast(e.message,true)}};
  }
  window.__czUsersForMessages=users;
  if(composeNew)renderNewConversationForm();
  else {const list=$('content')?.querySelector('.team-message-list');if(list)list.scrollTop=list.scrollHeight;}
}
function startNewTeamConversation(){const c=$('content');window.__czConversationId=null;window.__czTaskConversationId=null;window.__czComposeNew=true;window.__czShowInboxOnly=false;messagesPage(c).catch(e=>toast(e.message,true));}
